window.PACK={"book":{"id":"wasitiyya","title":"العقيدة الواسطية","type":"usulbook","ilm":"aqida","author":"ابن تيمية (ت ٧٢٨هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"أضواء السلف - الرياض","optional":true,"packVersion":"e6fbb1a8ac6a"},"items":[{"id":"wasitiyya:1","bookId":"wasitiyya","type":"section","seq":1,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"الكتاب: العقيدة الواسطية: اعتقاد الفرقة الناجية المنصورة إلى قيام الساعة أهل السنة والجماعة\nالمؤلف: تقي الدين أبو العباس أحمد بن عبد الحليم بن تيمية الحراني (المتوفى: 728ه)\nالمحقق: أبو محمد أشرف بن عبد المقصود\nالناشر: أضواء السلف - الرياض\nالطبعة: الثانية 1420ه / 1999م\nعدد الصفحات: 71\n[الكتاب مقابل، ومشكول، ومفهرس، وترقيم صفحاته موافق للمطبوع]\nبسم الله الرحمن الرحيم"},{"id":"wasitiyya:2","bookId":"wasitiyya","type":"section","seq":2,"chapter":"مقدمة المصنف","title":"مقدمة المصنف","page":"ص0","text":"] :\nالحمد لله الذي أرسل رسوله بالهدى ودين الحق؛ ليظهره على الدين كله وكفى بالله شهيدا.\nوأشهد أن لا إله إلا الله وحده لا شريك له؛ إقرارا به وتوحيدا.\nوأشهد أن محمدا عبده ورسوله.\nصلى الله عليه وعلى آله وسلم تسليما مزيدا.\nالمسألة الواسطية في العقيدة\nاعتقاد الفرقة الناجية المنصورة إلى قيام الساعة أهل السنة والجماعة"},{"id":"wasitiyya:3","bookId":"wasitiyya","type":"section","seq":3,"chapter":"مقدمة المصنف","title":"أصول الإيمان وأركانه الست","page":"ج1 ص53","text":"] :"},{"id":"wasitiyya:4","bookId":"wasitiyya","type":"section","seq":4,"chapter":"مقدمة المصنف","title":"1- الإيمان بالله","page":"ج1 ص53","text":"الإيمان بالله، وملائكته، وكتبه، ورسله، والبعث بعد الموت، والإيمان بالقدر؛ خيره وشره.\n* * * *"},{"id":"wasitiyya:5","bookId":"wasitiyya","type":"section","seq":5,"chapter":"مقدمة المصنف","title":"الباب الأول: الإيمان بالله تعالى ويشتمل على خمسة فصول: الفصل الأول: القواعد الأساسية في الإيمان بصفات الله. الفصل الثاني: الإيمان بما وصف ال","page":"ج1 ص54","text":"* * * *"},{"id":"wasitiyya:6","bookId":"wasitiyya","type":"section","seq":6,"chapter":"مقدمة المصنف","title":"2- ومن الإيمان بالله","page":"ج1 ص55","text":"ومن الإيمان بالله:\n- الإيمان بما وصف به نفسه في كتابه.\n- وبما وصفه به رسوله محمد صلى الله عليه وسلم."},{"id":"wasitiyya:7","bookId":"wasitiyya","type":"section","seq":7,"chapter":"مقدمة المصنف","title":"الابتعاد عن التحريف والتعطيل والتكييف والتمثيل","page":"ج1 ص55","text":"] :\nمن غير: تحريف ولا تعطيل، ومن غير: تكييف ولا تمثيل."},{"id":"wasitiyya:8","bookId":"wasitiyya","type":"section","seq":8,"chapter":"مقدمة المصنف","title":"3- بل يؤمنون بأن الله تعالى","page":"ج1 ص57","text":"بل يؤمنون بأن الله تعالى: {ليس كمثله شيء وهو السميع البصير} [الشورى: 11] ."},{"id":"wasitiyya:9","bookId":"wasitiyya","type":"section","seq":9,"chapter":"مقدمة المصنف","title":"4- فلا ينفون عنه","page":"ج1 ص57","text":"فلا ينفون عنه: ما وصف به نفسه."},{"id":"wasitiyya:10","bookId":"wasitiyya","type":"section","seq":10,"chapter":"مقدمة المصنف","title":"5- ولا يحرفون","page":"ج1 ص57","text":"ولا يحرفون: الكلم عن مواضعه."},{"id":"wasitiyya:11","bookId":"wasitiyya","type":"section","seq":11,"chapter":"مقدمة المصنف","title":"الإلحاد في أسماء الله وآياته","page":"ج1 ص57","text":"] :"},{"id":"wasitiyya:12","bookId":"wasitiyya","type":"section","seq":12,"chapter":"مقدمة المصنف","title":"6- ولا يلحدون في","page":"ج1 ص57","text":"ولا يلحدون في: أسماء الله، وآياته."},{"id":"wasitiyya:13","bookId":"wasitiyya","type":"section","seq":13,"chapter":"مقدمة المصنف","title":"7- ولا يمثلون","page":"ج1 ص57","text":"ولا يمثلون: صفاته بصفات خلقه."},{"id":"wasitiyya:14","bookId":"wasitiyya","type":"section","seq":14,"chapter":"مقدمة المصنف","title":"لا يقاس الله بخلقه","page":"ج1 ص57","text":"] :"},{"id":"wasitiyya:15","bookId":"wasitiyya","type":"section","seq":15,"chapter":"مقدمة المصنف","title":"8- لأنه سبحانه؛ لا سمي له","page":"ج1 ص57","text":"لأنه سبحانه؛ لا سمي له، ولا كفو له، ولا ند له، ولا يقاس بخلقه سبحانه وتعالى."},{"id":"wasitiyya:16","bookId":"wasitiyya","type":"section","seq":16,"chapter":"مقدمة المصنف","title":"9- فإنه سبحانه؛ أعلم بنفسه وبغيره","page":"ج1 ص57","text":"فإنه سبحانه؛ أعلم بنفسه وبغيره، وأصدق قيلا، وأحسن حديثا من خلقه."},{"id":"wasitiyya:17","bookId":"wasitiyya","type":"section","seq":17,"chapter":"مقدمة المصنف","title":"10- ثم رسله صادقون مصدقون؛ بخلاف الذين يقولون عليه ما لا يعلمون","page":"ج1 ص59","text":"ثم رسله صادقون مصدقون؛ بخلاف الذين يقولون عليه ما لا يعلمون."},{"id":"wasitiyya:18","bookId":"wasitiyya","type":"section","seq":18,"chapter":"مقدمة المصنف","title":"11- ولهذا قال سبحانه وتعالى","page":"ج1 ص59","text":"ولهذا قال سبحانه وتعالى: {سبحان ربك رب العزة عما يصفون • وسلام على المرسلين • والحمد لله رب العالمين} [الصافات: 180 - 182] ."},{"id":"wasitiyya:19","bookId":"wasitiyya","type":"section","seq":19,"chapter":"مقدمة المصنف","title":"12- فسبح نفسه عما وصفه به المخالفون للرسل","page":"ج1 ص59","text":"فسبح نفسه عما وصفه به المخالفون للرسل، وسلم على المرسلين لسلامة ما قالوه من النقص والعيب."},{"id":"wasitiyya:20","bookId":"wasitiyya","type":"section","seq":20,"chapter":"مقدمة المصنف","title":"13- وهو سبحانه قد جمع فيما وصف وسمى به نفسه بين","page":"ج1 ص59","text":"وهو سبحانه قد جمع فيما وصف وسمى به نفسه بين: النفي والإثبات."},{"id":"wasitiyya:21","bookId":"wasitiyya","type":"section","seq":21,"chapter":"مقدمة المصنف","title":"14- فلا عدول لأهل السنة والجماعة عما جاءت به المرسلون","page":"ج1 ص59","text":"فلا عدول لأهل السنة والجماعة عما جاءت به المرسلون."},{"id":"wasitiyya:22","bookId":"wasitiyya","type":"section","seq":22,"chapter":"مقدمة المصنف","title":"15- فإنه الصراط المستقيم","page":"ج1 ص59","text":"فإنه الصراط المستقيم، صراط الذين أنعم الله عليهم من النبيين، والصديقين، والشهداء، والصالحين.\n* * * *"},{"id":"wasitiyya:23","bookId":"wasitiyya","type":"section","seq":23,"chapter":"مقدمة المصنف","title":"الفصل الثاني: الإيمان بما وصف الله به نفسه في كتابه","page":"ج1 ص60","text":"• وقد دخل في هذه الجملة:"},{"id":"wasitiyya:24","bookId":"wasitiyya","type":"section","seq":24,"chapter":"مقدمة المصنف","title":"سورة الإخلاص تعدل ثلث القرآن","page":"ج1 ص60","text":"] :"},{"id":"wasitiyya:25","bookId":"wasitiyya","type":"section","seq":25,"chapter":"مقدمة المصنف","title":"16- ما وصف به نفسه في «سورة الإخلاص» التي تعدل ثلث القرآن","page":"ج1 ص60","text":"ما وصف به نفسه في «سورة الإخلاص» التي تعدل ثلث القرآن."},{"id":"wasitiyya:26","bookId":"wasitiyya","type":"section","seq":26,"chapter":"مقدمة المصنف","title":"17- حيث يقول","page":"ج1 ص60","text":"حيث يقول: {قل هو الله أحد • الله الصمد • لم يلد ولم يولد • ولم يكن له كفوا أحد} [الإخلاص: 1 - 4] .\n* * * *"},{"id":"wasitiyya:27","bookId":"wasitiyya","type":"section","seq":27,"chapter":"مقدمة المصنف","title":"آية الكرسي أعظم آية في كتاب الله","page":"ج1 ص60","text":"] :"},{"id":"wasitiyya:28","bookId":"wasitiyya","type":"section","seq":28,"chapter":"مقدمة المصنف","title":"18- وما وصف به نفسه في أعظم آية في كتابه","page":"ج1 ص60","text":"وما وصف به نفسه في أعظم آية في كتابه."},{"id":"wasitiyya:29","bookId":"wasitiyya","type":"section","seq":29,"chapter":"مقدمة المصنف","title":"19- حيث يقول","page":"ج1 ص60","text":"حيث يقول: {الله لا إله إلا هو الحي القيوم لا تأخذه سنة ولا نوم له ما في السموات وما في الأرض من ذا الذي يشفع عنده إلا بإذنه يعلم ما بين أيديهم وما خلفهم ولا يحيطون بشيء من علمه إلا بما شاء وسع كرسيه السموات والأرض ولا يئوده} - أي: لا يكرثه ولا يثقله - {حفظهما وهو العلي العظيم} [البقرة: 255] ."},{"id":"wasitiyya:30","bookId":"wasitiyya","type":"section","seq":30,"chapter":"مقدمة المصنف","title":"20- ولهذا كان من قرأ هذه الآية في ليلة؛ لم يزل عليه من الله حافظ","page":"ج1 ص61","text":"ولهذا كان من قرأ هذه الآية في ليلة؛ لم يزل عليه من الله حافظ، ولا يقربه شيطان حتى يصبح.\n* * * *"},{"id":"wasitiyya:31","bookId":"wasitiyya","type":"section","seq":31,"chapter":"مقدمة المصنف","title":"صفة الحياة","page":"ج1 ص61","text":"] :"},{"id":"wasitiyya:32","bookId":"wasitiyya","type":"section","seq":32,"chapter":"مقدمة المصنف","title":"21- وقوله سبحانه","page":"ج1 ص61","text":"وقوله سبحانه: {وتوكل على الحي الذي لا يموت} [الفرقان: 58] .\n* * * *"},{"id":"wasitiyya:33","bookId":"wasitiyya","type":"section","seq":33,"chapter":"مقدمة المصنف","title":"صفة العلم","page":"ج1 ص61","text":"] :"},{"id":"wasitiyya:34","bookId":"wasitiyya","type":"section","seq":34,"chapter":"مقدمة المصنف","title":"22- وقوله سبحانه","page":"ج1 ص61","text":"وقوله سبحانه: {هو الأول والآخر والظاهر والباطن وهو بكل شيء عليم} [الحديد: 3] ."},{"id":"wasitiyya:35","bookId":"wasitiyya","type":"section","seq":35,"chapter":"مقدمة المصنف","title":"23- وقوله سبحانه","page":"ج1 ص61","text":"وقوله سبحانه: {العليم الحكيم} [التحريم: 3] ."},{"id":"wasitiyya:36","bookId":"wasitiyya","type":"section","seq":36,"chapter":"مقدمة المصنف","title":"24-","page":"ج1 ص61","text":": {يعلم ما يلج في الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها} [سبأ: 2] ."},{"id":"wasitiyya:37","bookId":"wasitiyya","type":"section","seq":37,"chapter":"مقدمة المصنف","title":"25-","page":"ج1 ص61","text":": {وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا\nرطب ولا يابس إلا في كتاب مبين} [الأنعام: 59] ."},{"id":"wasitiyya:38","bookId":"wasitiyya","type":"section","seq":38,"chapter":"مقدمة المصنف","title":"26-","page":"ج1 ص62","text":": {وما تحمل من أنثى ولا تضع إلا بعلمه} [فاطر: 11] ."},{"id":"wasitiyya:39","bookId":"wasitiyya","type":"section","seq":39,"chapter":"مقدمة المصنف","title":"27- وقوله","page":"ج1 ص62","text":"وقوله: {لتعلموا أن الله على كل شيء قدير وأن الله قد أحاط بكل شيء علما} [الطلاق: 12] .\n* * * *"},{"id":"wasitiyya:40","bookId":"wasitiyya","type":"section","seq":40,"chapter":"مقدمة المصنف","title":"صفة القوة","page":"ج1 ص62","text":"] :"},{"id":"wasitiyya:41","bookId":"wasitiyya","type":"section","seq":41,"chapter":"مقدمة المصنف","title":"28- وقوله","page":"ج1 ص62","text":"وقوله: {إن الله هو الرزاق ذو القوة المتين} [الذاريات: 58] .\n* * * *"},{"id":"wasitiyya:42","bookId":"wasitiyya","type":"section","seq":42,"chapter":"مقدمة المصنف","title":"صفة السمع وصفة البصر","page":"ج1 ص62","text":"] :"},{"id":"wasitiyya:43","bookId":"wasitiyya","type":"section","seq":43,"chapter":"مقدمة المصنف","title":"29- وقوله","page":"ج1 ص62","text":"وقوله: {ليس كمثله شيء وهو السميع البصير} [الشورى: 11] ."},{"id":"wasitiyya:44","bookId":"wasitiyya","type":"section","seq":44,"chapter":"مقدمة المصنف","title":"30-","page":"ج1 ص62","text":": {إن الله نعما يعظكم به إن الله كان سميعا بصيرا} [النساء: 58] .\n* * * *"},{"id":"wasitiyya:45","bookId":"wasitiyya","type":"section","seq":45,"chapter":"مقدمة المصنف","title":"صفة الإرادة","page":"ج1 ص62","text":"] :"},{"id":"wasitiyya:46","bookId":"wasitiyya","type":"section","seq":46,"chapter":"مقدمة المصنف","title":"31- وقوله","page":"ج1 ص62","text":"وقوله: {ولولا إذ دخلت جنتك قلت ما شاء الله لا قوة إلا بالله} [الكهف: 39] ."},{"id":"wasitiyya:47","bookId":"wasitiyya","type":"section","seq":47,"chapter":"مقدمة المصنف","title":"32- وقوله","page":"ج1 ص62","text":"وقوله: {ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من آمن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد} [البقرة: 253] ."},{"id":"wasitiyya:48","bookId":"wasitiyya","type":"section","seq":48,"chapter":"مقدمة المصنف","title":"33- وقوله","page":"ج1 ص62","text":"وقوله: {أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم غير محلي الصيد وأنتم حرم إن الله يحكم ما يريد} [المائدة: 1] ."},{"id":"wasitiyya:49","bookId":"wasitiyya","type":"section","seq":49,"chapter":"مقدمة المصنف","title":"34- وقوله","page":"ج1 ص63","text":"وقوله: {فمن يرد الله أن يهديه يشرح صدره للإسلام ومن يرد أن يضله يجعل صدره ضيقا حرجا كأنما يصعد في السماء} [الأنعام: 125] .\n* * * *"},{"id":"wasitiyya:50","bookId":"wasitiyya","type":"section","seq":50,"chapter":"مقدمة المصنف","title":"صفة المحبة","page":"ج1 ص63","text":"] :"},{"id":"wasitiyya:51","bookId":"wasitiyya","type":"section","seq":51,"chapter":"مقدمة المصنف","title":"35- وقوله","page":"ج1 ص63","text":"وقوله: {وأحسنوا إن الله يحب المحسنين} [البقرة: 195] ."},{"id":"wasitiyya:52","bookId":"wasitiyya","type":"section","seq":52,"chapter":"مقدمة المصنف","title":"36-","page":"ج1 ص63","text":": {وأقسطوا إن الله يحب المقسطين} [الحجرات: 9] ."},{"id":"wasitiyya:53","bookId":"wasitiyya","type":"section","seq":53,"chapter":"مقدمة المصنف","title":"37-","page":"ج1 ص63","text":": {فما استقاموا لكم فاستقيموا لهم إن الله يحب المتقين} [التوبة: 7] ."},{"id":"wasitiyya:54","bookId":"wasitiyya","type":"section","seq":54,"chapter":"مقدمة المصنف","title":"38-","page":"ج1 ص63","text":": {إن الله يحب التوابين ويحب المتطهرين} [البقرة: 222] ."},{"id":"wasitiyya:55","bookId":"wasitiyya","type":"section","seq":55,"chapter":"مقدمة المصنف","title":"39-","page":"ج1 ص63","text":": {فسوف يأتي الله بقوم يحبهم ويحبونه} [المائدة: 54] ."},{"id":"wasitiyya:56","bookId":"wasitiyya","type":"section","seq":56,"chapter":"مقدمة المصنف","title":"40-","page":"ج1 ص63","text":": {إن الله يحب الذين يقاتلون في سبيله صفا كأنهم بنيان مرصوص} [الصف: 4] ."},{"id":"wasitiyya:57","bookId":"wasitiyya","type":"section","seq":57,"chapter":"مقدمة المصنف","title":"41-","page":"ج1 ص63","text":": {قل إن كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم} [آل عمران: 31] .\n* * * *"},{"id":"wasitiyya:58","bookId":"wasitiyya","type":"section","seq":58,"chapter":"مقدمة المصنف","title":"صفة الرضى","page":"ج1 ص63","text":"] :"},{"id":"wasitiyya:59","bookId":"wasitiyya","type":"section","seq":59,"chapter":"مقدمة المصنف","title":"42- وقوله","page":"ج1 ص63","text":"وقوله: {رضي الله عنهم ورضوا عنه} [البينة: 8] .\n* * * *"},{"id":"wasitiyya:60","bookId":"wasitiyya","type":"section","seq":60,"chapter":"مقدمة المصنف","title":"صفة الرحمة","page":"ج1 ص64","text":"] :"},{"id":"wasitiyya:61","bookId":"wasitiyya","type":"section","seq":61,"chapter":"مقدمة المصنف","title":"43- وقوله","page":"ج1 ص64","text":"وقوله: {بسم الله الرحمن الرحيم} [النمل: 30] ."},{"id":"wasitiyya:62","bookId":"wasitiyya","type":"section","seq":62,"chapter":"مقدمة المصنف","title":"44-","page":"ج1 ص64","text":": {ربنا وسعت كل شيء رحمة وعلما} [غافر: 7] ."},{"id":"wasitiyya:63","bookId":"wasitiyya","type":"section","seq":63,"chapter":"مقدمة المصنف","title":"45-","page":"ج1 ص64","text":": {وكان بالمؤمنين رحيما} [الأحزاب: 43] ."},{"id":"wasitiyya:64","bookId":"wasitiyya","type":"section","seq":64,"chapter":"مقدمة المصنف","title":"46-","page":"ج1 ص64","text":": {كتب ربكم على نفسه الرحمة} [الأنعام: 54] ."},{"id":"wasitiyya:65","bookId":"wasitiyya","type":"section","seq":65,"chapter":"مقدمة المصنف","title":"47-","page":"ج1 ص64","text":": {وهو الغفور الرحيم} [يونس: 107] ."},{"id":"wasitiyya:66","bookId":"wasitiyya","type":"section","seq":66,"chapter":"مقدمة المصنف","title":"48-","page":"ج1 ص64","text":": {فالله خير حافظا وهو أرحم الراحمين} [يوسف: 64] .\n* * * *"},{"id":"wasitiyya:67","bookId":"wasitiyya","type":"section","seq":67,"chapter":"مقدمة المصنف","title":"صفات: الغضب والسخط والكراهية والبغض","page":"ج1 ص64","text":"] :"},{"id":"wasitiyya:68","bookId":"wasitiyya","type":"section","seq":68,"chapter":"مقدمة المصنف","title":"49- وقوله","page":"ج1 ص64","text":"وقوله: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه} [النساء: 93] ."},{"id":"wasitiyya:69","bookId":"wasitiyya","type":"section","seq":69,"chapter":"مقدمة المصنف","title":"50- وقوله","page":"ج1 ص64","text":"وقوله: {ذلك بأنهم اتبعوا ما أسخط الله وكرهوا رضوانه} [محمد: 28] ."},{"id":"wasitiyya:70","bookId":"wasitiyya","type":"section","seq":70,"chapter":"مقدمة المصنف","title":"51- وقوله","page":"ج1 ص64","text":"وقوله: {فلما آسفونا انتقمنا منهم} [الزخرف: 55] ."},{"id":"wasitiyya:71","bookId":"wasitiyya","type":"section","seq":71,"chapter":"مقدمة المصنف","title":"52- وقوله","page":"ج1 ص64","text":"وقوله: {ولكن كره الله انبعاثهم فثبطهم} [التوبة: 46] ."},{"id":"wasitiyya:72","bookId":"wasitiyya","type":"section","seq":72,"chapter":"مقدمة المصنف","title":"53- وقوله","page":"ج1 ص64","text":"وقوله: {كبر مقتا عند الله أن تقولوا ما لا تفعلون} [الصف: 3] .\n* * * *"},{"id":"wasitiyya:73","bookId":"wasitiyya","type":"section","seq":73,"chapter":"مقدمة المصنف","title":"صفتي: المجيء والإتيان","page":"ج1 ص64","text":"] :"},{"id":"wasitiyya:74","bookId":"wasitiyya","type":"section","seq":74,"chapter":"مقدمة المصنف","title":"54- وقوله","page":"ج1 ص64","text":"وقوله: {هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام والملائكة وقضي الأمر} [البقرة: 210] ."},{"id":"wasitiyya:75","bookId":"wasitiyya","type":"section","seq":75,"chapter":"مقدمة المصنف","title":"55-","page":"ج1 ص65","text":": {هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك يوم يأتي بعض آيات ربك} [الأنعام: 158] ."},{"id":"wasitiyya:76","bookId":"wasitiyya","type":"section","seq":76,"chapter":"مقدمة المصنف","title":"56-","page":"ج1 ص65","text":": {كلا إذا دكت الأرض دكا دكا • وجاء ربك والملك صفا صفا} [الفجر: 21 - 22] ."},{"id":"wasitiyya:77","bookId":"wasitiyya","type":"section","seq":77,"chapter":"مقدمة المصنف","title":"57-","page":"ج1 ص65","text":": {ويوم تشقق السماء بالغمام ونزل الملائكة تنزيلا} [الفرقان: 25] .\n* * * *"},{"id":"wasitiyya:78","bookId":"wasitiyya","type":"section","seq":78,"chapter":"مقدمة المصنف","title":"صفة الوجه لله سبحانه","page":"ج1 ص65","text":"] :"},{"id":"wasitiyya:79","bookId":"wasitiyya","type":"section","seq":79,"chapter":"مقدمة المصنف","title":"58- وقوله","page":"ج1 ص65","text":"وقوله: {ويبقى وجه ربك ذو الجلال والإكرام} [الرحمن: 27] ."},{"id":"wasitiyya:80","bookId":"wasitiyya","type":"section","seq":80,"chapter":"مقدمة المصنف","title":"59-","page":"ج1 ص65","text":": {كل شيء هالك إلا وجهه} [القصص: 88] .\n* * * *"},{"id":"wasitiyya:81","bookId":"wasitiyya","type":"section","seq":81,"chapter":"مقدمة المصنف","title":"إثبات اليدين لله تعال","page":"ج1 ص65","text":"ى] :"},{"id":"wasitiyya:82","bookId":"wasitiyya","type":"section","seq":82,"chapter":"مقدمة المصنف","title":"60- وقوله","page":"ج1 ص65","text":"وقوله: {ما منعك أن تسجد لما خلقت بيدي} [ص: 75] ."},{"id":"wasitiyya:83","bookId":"wasitiyya","type":"section","seq":83,"chapter":"مقدمة المصنف","title":"61-","page":"ج1 ص65","text":": {وقالت اليهود يد الله مغلولة غلت أيديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء} [المائدة: 64] .\n* * * *"},{"id":"wasitiyya:84","bookId":"wasitiyya","type":"section","seq":84,"chapter":"مقدمة المصنف","title":"إثبات العينين لله تعالى","page":"ج1 ص65","text":"] :"},{"id":"wasitiyya:85","bookId":"wasitiyya","type":"section","seq":85,"chapter":"مقدمة المصنف","title":"62- وقوله","page":"ج1 ص65","text":"وقوله: {واصبر لحكم ربك فإنك بأعيننا} [الطور: 48] ."},{"id":"wasitiyya:86","bookId":"wasitiyya","type":"section","seq":86,"chapter":"مقدمة المصنف","title":"63-","page":"ج1 ص65","text":": {وحملناه على ذات ألواح ودسر • تجري بأعيننا جزاء لمن كان كفر} [القمر: 13 - 14] ."},{"id":"wasitiyya:87","bookId":"wasitiyya","type":"section","seq":87,"chapter":"مقدمة المصنف","title":"64-","page":"ج1 ص66","text":": {وألقيت عليك محبة مني ولتصنع على عيني} [طه: 39] .\n* * * *"},{"id":"wasitiyya:88","bookId":"wasitiyya","type":"section","seq":88,"chapter":"مقدمة المصنف","title":"صفتي السمع والبصر لله تعالى","page":"ج1 ص66","text":"] :"},{"id":"wasitiyya:89","bookId":"wasitiyya","type":"section","seq":89,"chapter":"مقدمة المصنف","title":"65- وقوله","page":"ج1 ص66","text":"وقوله: {قد سمع الله قول التي تجادلك في زوجها وتشتكي إلى الله والله يسمع تحاوركما إن الله سميع بصير} [المجادلة: 1] ."},{"id":"wasitiyya:90","bookId":"wasitiyya","type":"section","seq":90,"chapter":"مقدمة المصنف","title":"66-","page":"ج1 ص66","text":": {لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء سنكتب ما قالوا} [آل عمران: 181] ."},{"id":"wasitiyya:91","bookId":"wasitiyya","type":"section","seq":91,"chapter":"مقدمة المصنف","title":"67-","page":"ج1 ص66","text":": {أم يحسبون أنا لا نسمع سرهم ونجواهم بلى ورسلنا لديهم يكتبون} [الزخرف: 80] ."},{"id":"wasitiyya:92","bookId":"wasitiyya","type":"section","seq":92,"chapter":"مقدمة المصنف","title":"68-","page":"ج1 ص66","text":": {إنني معكما أسمع وأرى} [طه: 46] ."},{"id":"wasitiyya:93","bookId":"wasitiyya","type":"section","seq":93,"chapter":"مقدمة المصنف","title":"69-","page":"ج1 ص66","text":": {ألم يعلم بأن الله يرى} [العلق: 14] ."},{"id":"wasitiyya:94","bookId":"wasitiyya","type":"section","seq":94,"chapter":"مقدمة المصنف","title":"70-","page":"ج1 ص66","text":": {الذي يراك حين تقوم • وتقلبك في الساجدين} [الشعراء: 218 - 219] ."},{"id":"wasitiyya:95","bookId":"wasitiyya","type":"section","seq":95,"chapter":"مقدمة المصنف","title":"71-","page":"ج1 ص66","text":": {وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون} [التوبة: 105] .\n* * * *"},{"id":"wasitiyya:96","bookId":"wasitiyya","type":"section","seq":96,"chapter":"مقدمة المصنف","title":"72- وقوله","page":"ج1 ص66","text":"وقوله: {شديد المحال} [الرعد: 13] ."},{"id":"wasitiyya:97","bookId":"wasitiyya","type":"section","seq":97,"chapter":"مقدمة المصنف","title":"73- وقوله","page":"ج1 ص67","text":"وقوله: {ومكروا ومكر الله} [آل عمران: 54] ."},{"id":"wasitiyya:98","bookId":"wasitiyya","type":"section","seq":98,"chapter":"مقدمة المصنف","title":"74- وقوله","page":"ج1 ص67","text":"وقوله: {ومكروا مكرا ومكرنا مكرا وهم لا يشعرون} [النمل: 50] ."},{"id":"wasitiyya:99","bookId":"wasitiyya","type":"section","seq":99,"chapter":"مقدمة المصنف","title":"75- وقوله","page":"ج1 ص67","text":"وقوله: {إنهم يكيدون كيدا • وأكيد كيدا} [الطارق: 15 - 16] .\n* * * *"},{"id":"wasitiyya:100","bookId":"wasitiyya","type":"section","seq":100,"chapter":"مقدمة المصنف","title":"صفات العفو والمغفرة والرحمة والعزة والقدرة","page":"ج1 ص67","text":"] :"},{"id":"wasitiyya:101","bookId":"wasitiyya","type":"section","seq":101,"chapter":"مقدمة المصنف","title":"76- وقوله","page":"ج1 ص67","text":"وقوله: {إن تبدوا خيرا أو تخفوه أو تعفوا عن سوء فإن الله كان عفوا قديرا} [النساء: 149] ."},{"id":"wasitiyya:102","bookId":"wasitiyya","type":"section","seq":102,"chapter":"مقدمة المصنف","title":"77-","page":"ج1 ص67","text":": {وليعفوا وليصفحوا ألا تحبون أن يغفر الله لكم والله غفور رحيم} [النور: 22] ."},{"id":"wasitiyya:103","bookId":"wasitiyya","type":"section","seq":103,"chapter":"مقدمة المصنف","title":"78- وقوله","page":"ج1 ص67","text":"وقوله: {ولله العزة ولرسوله وللمؤمنين} [المنافقون: 8] ."},{"id":"wasitiyya:104","bookId":"wasitiyya","type":"section","seq":104,"chapter":"مقدمة المصنف","title":"79- وقوله عن إبليس","page":"ج1 ص67","text":"وقوله عن إبليس: {فبعزتك لأغوينهم أجمعين} [ص: 82] .\n* * * *"},{"id":"wasitiyya:105","bookId":"wasitiyya","type":"section","seq":105,"chapter":"مقدمة المصنف","title":"إثبات الاسم لله","page":"ج1 ص67","text":"] :"},{"id":"wasitiyya:106","bookId":"wasitiyya","type":"section","seq":106,"chapter":"مقدمة المصنف","title":"80- وقوله","page":"ج1 ص67","text":"وقوله: {تبارك اسم ربك ذي الجلال والإكرام} [الرحمن: 78] ."},{"id":"wasitiyya:107","bookId":"wasitiyya","type":"section","seq":107,"chapter":"مقدمة المصنف","title":"81- وقوله","page":"ج1 ص67","text":"وقوله: {فاعبده واصطبر لعبادته هل تعلم له سميا} [مريم: 65] .\n* * * *"},{"id":"wasitiyya:108","bookId":"wasitiyya","type":"section","seq":108,"chapter":"مقدمة المصنف","title":"آيات الصفات المنفية في تنزيه الله ونفي المثل عنه","page":"ج1 ص67","text":"] :"},{"id":"wasitiyya:109","bookId":"wasitiyya","type":"section","seq":109,"chapter":"مقدمة المصنف","title":"82- {ولم يكن له كفوا أحد} [الإخلاص","page":"ج1 ص67","text":"{ولم يكن له كفوا أحد} [الإخلاص: 4] ."},{"id":"wasitiyya:110","bookId":"wasitiyya","type":"section","seq":110,"chapter":"مقدمة المصنف","title":"83-","page":"ج1 ص68","text":": {فلا تجعلوا لله أندادا وأنتم تعلمون} [البقرة: 22] ."},{"id":"wasitiyya:111","bookId":"wasitiyya","type":"section","seq":111,"chapter":"مقدمة المصنف","title":"84-","page":"ج1 ص68","text":": {ومن الناس من يتخذ من دون الله أندادا يحبونهم كحب الله} [البقرة: 165] ."},{"id":"wasitiyya:112","bookId":"wasitiyya","type":"section","seq":112,"chapter":"مقدمة المصنف","title":"85-","page":"ج1 ص68","text":": {وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا} [الإسراء: 111] ."},{"id":"wasitiyya:113","bookId":"wasitiyya","type":"section","seq":113,"chapter":"مقدمة المصنف","title":"86-","page":"ج1 ص68","text":": {يسبح لله ما في السموات وما في الأرض له الملك وله الحمد وهو على كل شيء قدير} [التغابن: 1] ."},{"id":"wasitiyya:114","bookId":"wasitiyya","type":"section","seq":114,"chapter":"مقدمة المصنف","title":"87-","page":"ج1 ص68","text":": {تبارك الذي نزل الفرقان على عبده ليكون للعالمين نذيرا • الذي له ملك السموات والأرض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا} [الفرقان: 1 - 2] ."},{"id":"wasitiyya:115","bookId":"wasitiyya","type":"section","seq":115,"chapter":"مقدمة المصنف","title":"88-","page":"ج1 ص68","text":": {ما اتخذ الله من ولد وما كان معه من إله إذا لذهب كل إله بما خلق ولعلا بعضهم على بعض سبحان الله عما يصفون • عالم الغيب والشهادة فتعالى عما يشركون} [المؤمنون: 91 - 92] ."},{"id":"wasitiyya:116","bookId":"wasitiyya","type":"section","seq":116,"chapter":"مقدمة المصنف","title":"89-","page":"ج1 ص68","text":": {فلا تضربوا لله الأمثال إن الله يعلم وأنتم لا تعلمون} [النحل: 74] ."},{"id":"wasitiyya:117","bookId":"wasitiyya","type":"section","seq":117,"chapter":"مقدمة المصنف","title":"90-","page":"ج1 ص68","text":": {قل إنما حرم ربي الفواحش ما ظهر منها وما بطن والإثم\nوالبغي بغير الحق وأن تشركوا بالله ما لم ينزل به سلطانا وأن تقولوا على الله ما لا تعلمون} [الأعراف: 33] .\n* * * *"},{"id":"wasitiyya:118","bookId":"wasitiyya","type":"section","seq":118,"chapter":"مقدمة المصنف","title":"استواء الله على عرشه","page":"ج1 ص69","text":"] :"},{"id":"wasitiyya:119","bookId":"wasitiyya","type":"section","seq":119,"chapter":"مقدمة المصنف","title":"91- وقوله","page":"ج1 ص69","text":"وقوله: {الرحمن على العرش استوى} [طه: 5] ."},{"id":"wasitiyya:120","bookId":"wasitiyya","type":"section","seq":120,"chapter":"مقدمة المصنف","title":"92-","page":"ج1 ص69","text":": {ثم استوى على العرش} في ستة مواضع: [الأعراف: 54] [يونس: 3] [الرعد: 2] [الفرقان: 59] [السجدة: 4] [الحديد: 4] .\n* * * *"},{"id":"wasitiyya:121","bookId":"wasitiyya","type":"section","seq":121,"chapter":"مقدمة المصنف","title":"إثبات علو الله على مخلوقاته","page":"ج1 ص69","text":"] :"},{"id":"wasitiyya:122","bookId":"wasitiyya","type":"section","seq":122,"chapter":"مقدمة المصنف","title":"93-","page":"ج1 ص69","text":": {يا عيسى إني متوفيك ورافعك إلي} [آل عمران: 55] ."},{"id":"wasitiyya:123","bookId":"wasitiyya","type":"section","seq":123,"chapter":"مقدمة المصنف","title":"94-","page":"ج1 ص69","text":": {بل رفعه الله إليه} [النساء: 158] ."},{"id":"wasitiyya:124","bookId":"wasitiyya","type":"section","seq":124,"chapter":"مقدمة المصنف","title":"95-","page":"ج1 ص69","text":": {إليه يصعد الكلم الطيب والعمل الصالح يرفعه} [فاطر: 10] ."},{"id":"wasitiyya:125","bookId":"wasitiyya","type":"section","seq":125,"chapter":"مقدمة المصنف","title":"96-","page":"ج1 ص69","text":": {يا هامان ابن لي صرحا لعلي أبلغ الأسباب • أسباب السموات فأطلع إلى إله موسى وإني لأظنه كاذبا} [غافر: 36 - 37] ."},{"id":"wasitiyya:126","bookId":"wasitiyya","type":"section","seq":126,"chapter":"مقدمة المصنف","title":"97-","page":"ج1 ص69","text":": {أأمنتم من في السماء أن يخسف بكم الأرض فإذا هي تمور • أم أمنتم من في السماء أن يرسل عليكم حاصبا فستعلمون كيف نذير} [الملك: 16 - 17] .\n* * * *"},{"id":"wasitiyya:127","bookId":"wasitiyya","type":"section","seq":127,"chapter":"مقدمة المصنف","title":"إثبات معية الله لخلقه","page":"ج1 ص70","text":"] :"},{"id":"wasitiyya:128","bookId":"wasitiyya","type":"section","seq":128,"chapter":"مقدمة المصنف","title":"98- وقوله","page":"ج1 ص70","text":"وقوله: {هو الذي خلق السموات والأرض في ستة أيام ثم استوى على العرش يعلم ما يلج في الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم أين ما كنتم والله بما تعملون بصير} [الحديد: 4] ."},{"id":"wasitiyya:129","bookId":"wasitiyya","type":"section","seq":129,"chapter":"مقدمة المصنف","title":"99-","page":"ج1 ص70","text":": {ما يكون من نجوى ثلاثة إلا هو رابعهم ولا خمسة إلا هو سادسهم ولا أدنى من ذلك ولا أكثر إلا هو معهم أين ما كانوا ثم ينبئهم بما عملوا يوم القيامة إن الله بكل شيء عليم} [المجادلة: 7] ."},{"id":"wasitiyya:130","bookId":"wasitiyya","type":"section","seq":130,"chapter":"مقدمة المصنف","title":"100-","page":"ج1 ص70","text":": {لا تحزن إن الله معنا} [التوبة: 40] ."},{"id":"wasitiyya:131","bookId":"wasitiyya","type":"section","seq":131,"chapter":"مقدمة المصنف","title":"101-","page":"ج1 ص70","text":": {إنني معكما أسمع وأرى} [طه: 46] ."},{"id":"wasitiyya:132","bookId":"wasitiyya","type":"section","seq":132,"chapter":"مقدمة المصنف","title":"102-","page":"ج1 ص70","text":": {إن الله مع الذين اتقوا والذين هم محسنون} [النحل: 128] ."},{"id":"wasitiyya:133","bookId":"wasitiyya","type":"section","seq":133,"chapter":"مقدمة المصنف","title":"103-","page":"ج1 ص70","text":": {واصبروا إن الله مع الصابرين} [الأنفال: 46] ."},{"id":"wasitiyya:134","bookId":"wasitiyya","type":"section","seq":134,"chapter":"مقدمة المصنف","title":"104-","page":"ج1 ص70","text":": {كم من فئة قليلة غلبت فئة كثيرة بإذن الله والله مع الصابرين} [البقرة: 249] .\n* * * *"},{"id":"wasitiyya:135","bookId":"wasitiyya","type":"section","seq":135,"chapter":"مقدمة المصنف","title":"إثبات الكلام لله تعالى","page":"ج1 ص70","text":"] :"},{"id":"wasitiyya:136","bookId":"wasitiyya","type":"section","seq":136,"chapter":"مقدمة المصنف","title":"105- وقوله","page":"ج1 ص70","text":"وقوله: {ومن أصدق من الله حديثا} [النساء: 87] ."},{"id":"wasitiyya:137","bookId":"wasitiyya","type":"section","seq":137,"chapter":"مقدمة المصنف","title":"106-","page":"ج1 ص71","text":": {ومن أصدق من الله قيلا} [النساء: 122] ."},{"id":"wasitiyya:138","bookId":"wasitiyya","type":"section","seq":138,"chapter":"مقدمة المصنف","title":"107-","page":"ج1 ص71","text":": {وإذ قال الله يا عيسى ابن مريم} [المائدة: 116] ."},{"id":"wasitiyya:139","bookId":"wasitiyya","type":"section","seq":139,"chapter":"مقدمة المصنف","title":"108-","page":"ج1 ص71","text":": {وتمت كلمة ربك صدقا وعدلا} [الأنعام: 115] ."},{"id":"wasitiyya:140","bookId":"wasitiyya","type":"section","seq":140,"chapter":"مقدمة المصنف","title":"109-","page":"ج1 ص71","text":": {وكلم الله موسى تكليما} [النساء: 164] ."},{"id":"wasitiyya:141","bookId":"wasitiyya","type":"section","seq":141,"chapter":"مقدمة المصنف","title":"110-","page":"ج1 ص71","text":": {منهم من كلم الله} [البقرة: 253] ."},{"id":"wasitiyya:142","bookId":"wasitiyya","type":"section","seq":142,"chapter":"مقدمة المصنف","title":"111-","page":"ج1 ص71","text":": {ولما جاء موسى لميقاتنا وكلمه ربه} [الأعراف: 143] .\n* * * *"},{"id":"wasitiyya:143","bookId":"wasitiyya","type":"section","seq":143,"chapter":"مقدمة المصنف","title":"112-","page":"ج1 ص71","text":": {وناديناه من جانب الطور الأيمن وقربناه نجيا} [مريم: 52] ."},{"id":"wasitiyya:144","bookId":"wasitiyya","type":"section","seq":144,"chapter":"مقدمة المصنف","title":"113-","page":"ج1 ص71","text":": {وإذ نادى ربك موسى أن ائت القوم الظالمين} [الشعراء: 10] ."},{"id":"wasitiyya:145","bookId":"wasitiyya","type":"section","seq":145,"chapter":"مقدمة المصنف","title":"114-","page":"ج1 ص71","text":": {وناداهما ربهما ألم أنهكما عن تلكما الشجرة} [الأعراف: 22] ."},{"id":"wasitiyya:146","bookId":"wasitiyya","type":"section","seq":146,"chapter":"مقدمة المصنف","title":"115-","page":"ج1 ص71","text":": {ويوم يناديهم فيقول أين شركائي الذين كنتم تزعمون} [القصص: 62] ."},{"id":"wasitiyya:147","bookId":"wasitiyya","type":"section","seq":147,"chapter":"مقدمة المصنف","title":"116-","page":"ج1 ص71","text":": {ويوم يناديهم فيقول ماذا أجبتم المرسلين} [القصص: 65] .\n* * * *"},{"id":"wasitiyya:148","bookId":"wasitiyya","type":"section","seq":148,"chapter":"مقدمة المصنف","title":"117-","page":"ج1 ص71","text":": {وإن أحد من المشركين استجارك فأجره حتى يسمع كلام الله} [التوبة: 6] ."},{"id":"wasitiyya:149","bookId":"wasitiyya","type":"section","seq":149,"chapter":"مقدمة المصنف","title":"118-","page":"ج1 ص72","text":": {وقد كان فريق منهم يسمعون كلام الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون} [البقرة: 75] ."},{"id":"wasitiyya:150","bookId":"wasitiyya","type":"section","seq":150,"chapter":"مقدمة المصنف","title":"119-","page":"ج1 ص72","text":": {يريدون أن يبدلوا كلام الله قل لن تتبعونا} [الفتح: 15] ."},{"id":"wasitiyya:151","bookId":"wasitiyya","type":"section","seq":151,"chapter":"مقدمة المصنف","title":"120-","page":"ج1 ص72","text":": {واتل ما أوحي إليك من كتاب ربك لا مبدل لكلماته} [الكهف: 27] ."},{"id":"wasitiyya:152","bookId":"wasitiyya","type":"section","seq":152,"chapter":"مقدمة المصنف","title":"121-","page":"ج1 ص72","text":": {إن هذا القرآن يقص على بني إسرائيل} [النمل: 76] .\n* * * *"},{"id":"wasitiyya:153","bookId":"wasitiyya","type":"section","seq":153,"chapter":"مقدمة المصنف","title":"122-","page":"ج1 ص72","text":": {وهذا كتاب أنزلناه مبارك} [الأنعام: 155] ."},{"id":"wasitiyya:154","bookId":"wasitiyya","type":"section","seq":154,"chapter":"مقدمة المصنف","title":"123-","page":"ج1 ص72","text":": {لو أنزلنا هذا القرآن على جبل لرأيته خاشعا متصدعا من خشية الله} [الحشر: 21] ."},{"id":"wasitiyya:155","bookId":"wasitiyya","type":"section","seq":155,"chapter":"مقدمة المصنف","title":"124-","page":"ج1 ص72","text":": {وإذا بدلنا آية مكان آية والله أعلم بما ينزل قالوا إنما أنت مفتر بل أكثرهم لا يعلمون • قل نزله روح القدس من ربك بالحق ليثبت الذين آمنوا وهدى وبشرى للمسلمين • ولقد نعلم أنهم يقولون إنما يعلمه بشر لسان الذي يلحدون إليه أعجمي وهذا لسان عربي مبين} [النحل: 101 - 103] .\n* * * *"},{"id":"wasitiyya:156","bookId":"wasitiyya","type":"section","seq":156,"chapter":"مقدمة المصنف","title":"إثبات رؤية المؤمنين لربهم يوم القيامة","page":"ج1 ص73","text":"] :"},{"id":"wasitiyya:157","bookId":"wasitiyya","type":"section","seq":157,"chapter":"مقدمة المصنف","title":"125- وقوله","page":"ج1 ص73","text":"وقوله: {وجوه يومئذ ناضرة • إلى ربها ناظرة} [القيامة: 22 - 23] ."},{"id":"wasitiyya:158","bookId":"wasitiyya","type":"section","seq":158,"chapter":"مقدمة المصنف","title":"126-","page":"ج1 ص73","text":": {على الأرائك ينظرون} [المطففين: 24] ."},{"id":"wasitiyya:159","bookId":"wasitiyya","type":"section","seq":159,"chapter":"مقدمة المصنف","title":"127-","page":"ج1 ص73","text":": {للذين أحسنوا الحسنى وزيادة} [يونس: 26] ."},{"id":"wasitiyya:160","bookId":"wasitiyya","type":"section","seq":160,"chapter":"مقدمة المصنف","title":"128-","page":"ج1 ص73","text":": {لهم ما يشاءون فيها ولدينا مزيد} [ق: 35] ."},{"id":"wasitiyya:161","bookId":"wasitiyya","type":"section","seq":161,"chapter":"مقدمة المصنف","title":"129- وهذا الباب في كتاب الله تعالى كثير","page":"ج1 ص73","text":"وهذا الباب في كتاب الله تعالى كثير."},{"id":"wasitiyya:162","bookId":"wasitiyya","type":"section","seq":162,"chapter":"مقدمة المصنف","title":"130- ومن تدبر القرآن طالبا للهدى منه؛ تبين له طريق الحق","page":"ج1 ص73","text":"ومن تدبر القرآن طالبا للهدى منه؛ تبين له طريق الحق.\n* * * *"},{"id":"wasitiyya:163","bookId":"wasitiyya","type":"section","seq":163,"chapter":"مقدمة المصنف","title":"الفصل الثالث: الإيمان بما وصف به الرسول صلى الله عليه وسلم ربه","page":"ج1 ص74","text":"• ثم سنة رسول الله صلى الله عليه وسلم:"},{"id":"wasitiyya:164","bookId":"wasitiyya","type":"section","seq":164,"chapter":"مقدمة المصنف","title":"131- تفسر القرآن","page":"ج1 ص74","text":"تفسر القرآن، وتبينه، وتدل عليه، وتعبر عنه."},{"id":"wasitiyya:165","bookId":"wasitiyya","type":"section","seq":165,"chapter":"مقدمة المصنف","title":"132- وما وصف الرسول به ربه","page":"ج1 ص74","text":"وما وصف الرسول به ربه، من الأحاديث الصحاح التي تلقاها أهل المعرفة بالقبول؛ وجب الإيمان بها كذلك.\n* * * *"},{"id":"wasitiyya:166","bookId":"wasitiyya","type":"section","seq":166,"chapter":"مقدمة المصنف","title":"أحاديث الصفات","page":"ج1 ص74","text":"] :"},{"id":"wasitiyya:167","bookId":"wasitiyya","type":"section","seq":167,"chapter":"مقدمة المصنف","title":"1- في إثبات نزول الله إلى السماء الدنيا","page":"ج1 ص74","text":"] :"},{"id":"wasitiyya:168","bookId":"wasitiyya","type":"section","seq":168,"chapter":"مقدمة المصنف","title":"133- مثل قوله صلى الله عليه وسلم","page":"ج1 ص74","text":"مثل قوله صلى الله عليه وسلم: «ينزل ربنا إلى سماء الدنيا كل ليلة، حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له» . متفق عليه.\n* * * *"},{"id":"wasitiyya:169","bookId":"wasitiyya","type":"section","seq":169,"chapter":"مقدمة المصنف","title":"2- في إثبات الفرح لله عز وجل","page":"ج1 ص74","text":"] :"},{"id":"wasitiyya:170","bookId":"wasitiyya","type":"section","seq":170,"chapter":"مقدمة المصنف","title":"134- وقوله صلى الله عليه وسلم","page":"ج1 ص74","text":"وقوله صلى الله عليه وسلم: «لله أشد فرحا بتوبة عبده، من أحدكم براحلته ... » الحديث. متفق عليه."},{"id":"wasitiyya:171","bookId":"wasitiyya","type":"section","seq":171,"chapter":"مقدمة المصنف","title":"3- في إثبات الضحك","page":"ج1 ص75","text":"] :"},{"id":"wasitiyya:172","bookId":"wasitiyya","type":"section","seq":172,"chapter":"مقدمة المصنف","title":"135- وقوله صلى الله عليه وسلم","page":"ج1 ص75","text":"وقوله صلى الله عليه وسلم: «يضحك الله إلى رجلين؛ يقتل أحدهما الآخر؛ كلاهما يدخل الجنة» . متفق عليه.\n* * * *"},{"id":"wasitiyya:173","bookId":"wasitiyya","type":"section","seq":173,"chapter":"مقدمة المصنف","title":"4- في إثبات العجب وصفات أخرى","page":"ج1 ص75","text":"] :"},{"id":"wasitiyya:174","bookId":"wasitiyya","type":"section","seq":174,"chapter":"مقدمة المصنف","title":"136- وقوله صلى الله عليه وسلم","page":"ج1 ص75","text":"وقوله صلى الله عليه وسلم: «عجب ربنا من قنوط عباده وقرب غيره؛ ينظر إليكم أزلين قنطين، فيظل يضحك؛ يعلم أن فرجكم قريب» . حديث حسن.\n* * * *"},{"id":"wasitiyya:175","bookId":"wasitiyya","type":"section","seq":175,"chapter":"مقدمة المصنف","title":"5- في إثبات الرجل أو القدم","page":"ج1 ص75","text":"] :"},{"id":"wasitiyya:176","bookId":"wasitiyya","type":"section","seq":176,"chapter":"مقدمة المصنف","title":"137- وقوله صلى الله عليه وسلم","page":"ج1 ص75","text":"وقوله صلى الله عليه وسلم: «لا تزال جهنم يلقى فيها، وتقول: هل من مزيد؛ حتى يضع رب العزة فيها - وفي رواية: عليها - قدمه\nفينزوي بعضها إلى بعض؛ وتقول: قط قط» . متفق عليه.\n* * * *"},{"id":"wasitiyya:177","bookId":"wasitiyya","type":"section","seq":177,"chapter":"مقدمة المصنف","title":"6- في إثبات الكلام والصوت","page":"ج1 ص76","text":"] :"},{"id":"wasitiyya:178","bookId":"wasitiyya","type":"section","seq":178,"chapter":"مقدمة المصنف","title":"138- وقوله صلى الله عليه وسلم","page":"ج1 ص76","text":"وقوله صلى الله عليه وسلم: «يقول الله تعالى: يا آدم! فيقول: لبيك وسعديك. فينادي بصوت: إن الله يأمرك أن تخرج من ذريتك بعثا إلى النار..» . متفق عليه.\n* * * *"},{"id":"wasitiyya:179","bookId":"wasitiyya","type":"section","seq":179,"chapter":"مقدمة المصنف","title":"139- وقوله صلى الله عليه وسلم","page":"ج1 ص76","text":"وقوله صلى الله عليه وسلم: «ما منكم من أحد إلا سيكلمه ربه، ليس بينه وبينه حاجب ولا ترجمان» .\n* * * *"},{"id":"wasitiyya:180","bookId":"wasitiyya","type":"section","seq":180,"chapter":"مقدمة المصنف","title":"7- في إثبات العلو لله وصفات أخرى","page":"ج1 ص76","text":"] :"},{"id":"wasitiyya:181","bookId":"wasitiyya","type":"section","seq":181,"chapter":"مقدمة المصنف","title":"140- وقوله صلى الله عليه وسلم في رقية المريض","page":"ج1 ص76","text":"وقوله صلى الله عليه وسلم في رقية المريض: «ربنا الله الذي في السماء! تقدس اسمك، أمرك في السماء والأرض؛ كما رحمتك في السماء؛ اجعل رحمتك في الأرض، اغفر لنا حوبنا\nوخطايانا، أنت رب الطيبين، أنزل رحمة من رحمتك وشفاء من شفائك على هذا الوجع» . رواه «أبو داود» .\n* * * *"},{"id":"wasitiyya:182","bookId":"wasitiyya","type":"section","seq":182,"chapter":"مقدمة المصنف","title":"141- وقوله صلى الله عليه وسلم","page":"ج1 ص77","text":"وقوله صلى الله عليه وسلم: «ألا تأمنوني وأنا أمين من في السماء» . رواه «البخاري» وغيره.\n* * * *"},{"id":"wasitiyya:183","bookId":"wasitiyya","type":"section","seq":183,"chapter":"مقدمة المصنف","title":"142- وقوله صلى الله عليه وسلم","page":"ج1 ص77","text":"وقوله صلى الله عليه وسلم: «والعرش فوق ذلك، والله فوق العرش وهو يعلم ما أنتم عليه» . رواه «أبو داود» «والترمذي» وغيرهما."},{"id":"wasitiyya:184","bookId":"wasitiyya","type":"section","seq":184,"chapter":"مقدمة المصنف","title":"143- وقوله عليه السلام للجارية","page":"ج1 ص78","text":"وقوله عليه السلام للجارية: «أين الله؟» .\nقالت: في السماء.\nقال: «من أنا؟» .\nقالت: أنت رسول الله.\nقال: «أعتقها؛ فإنها مؤمنة» . رواه «مسلم» .\n* * * *"},{"id":"wasitiyya:185","bookId":"wasitiyya","type":"section","seq":185,"chapter":"مقدمة المصنف","title":"11- في إثبات المعية","page":"ج1 ص78","text":"] :"},{"id":"wasitiyya:186","bookId":"wasitiyya","type":"section","seq":186,"chapter":"مقدمة المصنف","title":"144- وقوله صلى الله عليه وسلم","page":"ج1 ص78","text":"وقوله صلى الله عليه وسلم: «أفضل الإيمان: أن تعلم أن الله معك حيثما كنت» . حديث حسن.\n* * * *"},{"id":"wasitiyya:187","bookId":"wasitiyya","type":"section","seq":187,"chapter":"مقدمة المصنف","title":"12- في إثبات كون الله قبل وجه المصلي","page":"ج1 ص78","text":"] :"},{"id":"wasitiyya:188","bookId":"wasitiyya","type":"section","seq":188,"chapter":"مقدمة المصنف","title":"145- وقوله","page":"ج1 ص78","text":"وقوله: «إذا قام أحدكم إلى الصلاة؛ فإن الله قبل وجهه؛ فلا يبصقن قبل وجهه، ولا عن يمينه، ولكن عن يساره، أو تحت قدمه» . متفق عليه."},{"id":"wasitiyya:189","bookId":"wasitiyya","type":"section","seq":189,"chapter":"مقدمة المصنف","title":"13- في إثبات العلو وصفات أخرى","page":"ج1 ص79","text":"] :"},{"id":"wasitiyya:190","bookId":"wasitiyya","type":"section","seq":190,"chapter":"مقدمة المصنف","title":"146- وقوله صلى الله عليه وسلم","page":"ج1 ص79","text":"وقوله صلى الله عليه وسلم: «اللهم! رب السماوات السبع، ورب العرش العظيم! ربنا ورب كل شيء! فالق الحب والنوى! منزل التوراة والإنجيل والقرآن! أعوذ بك من شر كل دابة أنت آخذ بناصيتها. اللهم أنت الأول؛ فليس قبلك شيء، وأنت الآخر؛ فليس بعدك شيء، وأنت الظاهر؛ فليس فوقك شيء، وأنت الباطن؛ فليس دونك شيء، اقض عني الدين، وأغنني من الفقر» . رواه «مسلم» .\n* * * *"},{"id":"wasitiyya:191","bookId":"wasitiyya","type":"section","seq":191,"chapter":"مقدمة المصنف","title":"14- في إثبات قرب الله تعالى","page":"ج1 ص79","text":"] :"},{"id":"wasitiyya:192","bookId":"wasitiyya","type":"section","seq":192,"chapter":"مقدمة المصنف","title":"147- وقوله صلى الله عليه وسلم لما رفع أصحابه أصواتهم بالذكر","page":"ج1 ص79","text":"وقوله صلى الله عليه وسلم لما رفع أصحابه أصواتهم بالذكر: «أيها الناس! اربعوا على أنفسكم؛ فإنكم لا تدعون أصم ولا غائبا؛ إنما تدعون سميعا قريبا؛ إن الذي تدعونه أقرب إلى أحدكم من عنق راحلته» . متفق عليه.\n* * * *"},{"id":"wasitiyya:193","bookId":"wasitiyya","type":"section","seq":193,"chapter":"مقدمة المصنف","title":"15- إثبات رؤية المؤمنين لربهم","page":"ج1 ص80","text":"] :"},{"id":"wasitiyya:194","bookId":"wasitiyya","type":"section","seq":194,"chapter":"مقدمة المصنف","title":"148- وقوله صلى الله عليه وسلم","page":"ج1 ص80","text":"وقوله صلى الله عليه وسلم: «إنكم سترون ربكم؛ كما ترون القمر ليلة البدر لا تضامون في رؤيته؛ فإن استطعتم أن لا تغلبوا على صلاة قبل طلوع الشمس، وصلاة قبل غروبها؛ فافعلوا» . متفق عليه.\n* * * *"},{"id":"wasitiyya:195","bookId":"wasitiyya","type":"section","seq":195,"chapter":"مقدمة المصنف","title":"149- إلى أمثال هذه الأحاديث التي يخبر فيها رسول الله عن ربه؛ بما يخبر به","page":"ج1 ص80","text":"إلى أمثال هذه الأحاديث التي يخبر فيها رسول الله عن ربه؛ بما يخبر به."},{"id":"wasitiyya:196","bookId":"wasitiyya","type":"section","seq":196,"chapter":"مقدمة المصنف","title":"150- فإن الفرقة الناجية أهل السنة والجماعة يؤمنون بذلك","page":"ج1 ص80","text":"فإن الفرقة الناجية أهل السنة والجماعة يؤمنون بذلك.\nكما يؤمنون بما أخبر الله به في كتابه، من غير: تحريف ولا تعطيل، ومن غير: تكييف ولا تمثيل.\n* * * *"},{"id":"wasitiyya:197","bookId":"wasitiyya","type":"section","seq":197,"chapter":"مقدمة المصنف","title":"151- بل هم الوسط في فرق الأمة؛ كما أن الأمة هي الوسط في الأمم","page":"ج1 ص81","text":"بل هم الوسط في فرق الأمة؛ كما أن الأمة هي الوسط في الأمم."},{"id":"wasitiyya:198","bookId":"wasitiyya","type":"section","seq":198,"chapter":"مقدمة المصنف","title":"الأصل الأول: باب الأسماء والصفات","page":"ج1 ص81","text":"] :"},{"id":"wasitiyya:199","bookId":"wasitiyya","type":"section","seq":199,"chapter":"مقدمة المصنف","title":"152- فهم وسط في","page":"ج1 ص81","text":"فهم وسط في: باب صفات الله سبحانه وتعالى.\nبين أهل التعطيل «الجهمية» ، وبين أهل التمثيل «المشبهة» ."},{"id":"wasitiyya:200","bookId":"wasitiyya","type":"section","seq":200,"chapter":"مقدمة المصنف","title":"الأصل الثاني: أفعال الله","page":"ج1 ص81","text":"] :"},{"id":"wasitiyya:201","bookId":"wasitiyya","type":"section","seq":201,"chapter":"مقدمة المصنف","title":"153- وهم وسط في","page":"ج1 ص81","text":"وهم وسط في: باب أفعال الله تعالى.\nبين «القدرية» ، «والجبرية» ."},{"id":"wasitiyya:202","bookId":"wasitiyya","type":"section","seq":202,"chapter":"مقدمة المصنف","title":"الأصل الثالث: الوعيد","page":"ج1 ص81","text":"] :"},{"id":"wasitiyya:203","bookId":"wasitiyya","type":"section","seq":203,"chapter":"مقدمة المصنف","title":"154- وفي","page":"ج1 ص81","text":"وفي: باب وعيد الله.\nبين «المرجئة» ، وبين «الوعيدية» من «القدرية» وغيرهم."},{"id":"wasitiyya:204","bookId":"wasitiyya","type":"section","seq":204,"chapter":"مقدمة المصنف","title":"الأصل الرابع: أسماء الإيمان والدين","page":"ج1 ص81","text":"] :"},{"id":"wasitiyya:205","bookId":"wasitiyya","type":"section","seq":205,"chapter":"مقدمة المصنف","title":"155- وفي","page":"ج1 ص81","text":"وفي: باب الإيمان والدين.\nبين «الحرورية» «والمعتزلة» ، وبين «المرجئة» «والجهمية» ."},{"id":"wasitiyya:206","bookId":"wasitiyya","type":"section","seq":206,"chapter":"مقدمة المصنف","title":"الأصل الخامس: في الصحابة رضي الله عنهم","page":"ج1 ص81","text":"] :"},{"id":"wasitiyya:207","bookId":"wasitiyya","type":"section","seq":207,"chapter":"مقدمة المصنف","title":"156- وفي","page":"ج1 ص81","text":"وفي: أصحاب رسول الله صلى الله عليه وسلم.\nبين «الروافض» ، وبين «الخوارج» .\n* * * *"},{"id":"wasitiyya:208","bookId":"wasitiyya","type":"section","seq":208,"chapter":"مقدمة المصنف","title":"الفصل الخامس: يدخل في الإيمان بالله: أنه سبحانه فوق سماواته، علي على عرشه","page":"ج1 ص82","text":"• وقد دخل فيما ذكرناه من الإيمان بالله:"},{"id":"wasitiyya:209","bookId":"wasitiyya","type":"section","seq":209,"chapter":"مقدمة المصنف","title":"157- الإيمان بما أخبر الله به في كتابه","page":"ج1 ص82","text":"الإيمان بما أخبر الله به في كتابه، وتواتر عن رسوله صلى الله عليه وسلم، وأجمع عليه سلف الأمة:\n- من أنه سبحانه فوق سماواته على عرشه، علي على خلقه.\n- وهو سبحانه معهم أينما كانوا؛ يعلم ما هم عاملون."},{"id":"wasitiyya:210","bookId":"wasitiyya","type":"section","seq":210,"chapter":"مقدمة المصنف","title":"158- كما جمع بين ذلك في قوله","page":"ج1 ص82","text":"كما جمع بين ذلك في قوله: {هو الذي خلق السموات والأرض في ستة أيام ثم استوى على العرش يعلم ما يلج في الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم أين ما كنتم والله بما تعملون بصير} [الحديد: 4] ."},{"id":"wasitiyya:211","bookId":"wasitiyya","type":"section","seq":211,"chapter":"مقدمة المصنف","title":"159- وليس معنى قوله","page":"ج1 ص82","text":"وليس معنى قوله: {وهو معكم} أنه مختلط بالخلق.\n- فإن هذا لا توجبه اللغة.\n- وهو خلاف ما أجمع عليه سلف الأمة.\n- وخلاف ما فطر الله عليه الخلق."},{"id":"wasitiyya:212","bookId":"wasitiyya","type":"section","seq":212,"chapter":"مقدمة المصنف","title":"160- بل «القمر» آية من آيات الله","page":"ج1 ص83","text":"بل «القمر» آية من آيات الله، من أصغر مخلوقاته، هو موضوع في السماء، وهو مع المسافر، وغير المسافر أينما كان.\n* * * *"},{"id":"wasitiyya:213","bookId":"wasitiyya","type":"section","seq":213,"chapter":"مقدمة المصنف","title":"161- وهو سبحانه فوق العرش","page":"ج1 ص83","text":"وهو سبحانه فوق العرش، رقيب على خلقه، مهيمن عليهم مطلع إليهم؛ إلى غير ذلك من معاني ربوبيته."},{"id":"wasitiyya:214","bookId":"wasitiyya","type":"section","seq":214,"chapter":"مقدمة المصنف","title":"162- وكل هذا الكلام الذي ذكره الله؛ من","page":"ج1 ص83","text":"وكل هذا الكلام الذي ذكره الله؛ من: أنه فوق العرش، وأنه معنا؛ حق على حقيقته، لا يحتاج إلى تحريف، ولكن يصان عن الظنون الكاذبة."},{"id":"wasitiyya:215","bookId":"wasitiyya","type":"section","seq":215,"chapter":"مقدمة المصنف","title":"الفصل السادس: يدخل في الإيمان بالله: أنه قريب من خلقه","page":"ج1 ص84","text":"• وقد دخل في ذلك:"},{"id":"wasitiyya:216","bookId":"wasitiyya","type":"section","seq":216,"chapter":"مقدمة المصنف","title":"163- الإيمان بأنه قريب من خلقه","page":"ج1 ص84","text":"الإيمان بأنه قريب من خلقه."},{"id":"wasitiyya:217","bookId":"wasitiyya","type":"section","seq":217,"chapter":"مقدمة المصنف","title":"164- كما قال سبحانه وتعالى","page":"ج1 ص84","text":"كما قال سبحانه وتعالى: {وإذا سألك عبادي عني فإني قريب أجيب دعوة الداع إذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون} [البقرة: 186] ."},{"id":"wasitiyya:218","bookId":"wasitiyya","type":"section","seq":218,"chapter":"مقدمة المصنف","title":"165- وقال النبي صلى الله عليه وسلم","page":"ج1 ص84","text":"وقال النبي صلى الله عليه وسلم: «إن الذي تدعونه، أقرب إلى أحدكم من عنق راحلته» ."},{"id":"wasitiyya:219","bookId":"wasitiyya","type":"section","seq":219,"chapter":"مقدمة المصنف","title":"166- وما ذكر في الكتاب والسنة","page":"ج1 ص84","text":"وما ذكر في الكتاب والسنة، من قربه ومعيته، لا ينافي ما نذكر من علوه وفوقيته؛ فإنه سبحانه ليس كمثله شيء في جميع نعوته، وهو علي في دنوه، قريب في علوه.\n* * * *"},{"id":"wasitiyya:220","bookId":"wasitiyya","type":"section","seq":220,"chapter":"مقدمة المصنف","title":"الفصل الأول: الإيمان بأن القرآن كلام الله منزل غير مخلوق","page":"ج1 ص85","text":"الفصل الثاني: الإيمان بأن المؤمنين يرون ربهم يوم القيامة.]"},{"id":"wasitiyya:221","bookId":"wasitiyya","type":"section","seq":221,"chapter":"مقدمة المصنف","title":"الفصل الأول: الإيمان بأن القرآن كلام الله منزل غير مخلوق","page":"ج1 ص87","text":"• ومن الإيمان به وبكتبه:"},{"id":"wasitiyya:222","bookId":"wasitiyya","type":"section","seq":222,"chapter":"مقدمة المصنف","title":"167- الإيمان بأن القرآن كلام الله","page":"ج1 ص87","text":"الإيمان بأن القرآن كلام الله، منزل، غير مخلوق."},{"id":"wasitiyya:223","bookId":"wasitiyya","type":"section","seq":223,"chapter":"مقدمة المصنف","title":"168- منه بدأ","page":"ج1 ص87","text":"منه بدأ، وإليه يعود."},{"id":"wasitiyya:224","bookId":"wasitiyya","type":"section","seq":224,"chapter":"مقدمة المصنف","title":"169- وأن الله تكلم به حقيقة","page":"ج1 ص87","text":"وأن الله تكلم به حقيقة."},{"id":"wasitiyya:225","bookId":"wasitiyya","type":"section","seq":225,"chapter":"مقدمة المصنف","title":"170- وأن هذا القرآن الذي أنزله على نبيه محمد صلى الله عليه وسلم","page":"ج1 ص89","text":"وأن هذا القرآن الذي أنزله على نبيه محمد صلى الله عليه وسلم، هو كلام الله حقيقة، لا كلام غيره."},{"id":"wasitiyya:226","bookId":"wasitiyya","type":"section","seq":226,"chapter":"مقدمة المصنف","title":"171- ولا يجوز إطلاق القول","page":"ج1 ص89","text":"ولا يجوز إطلاق القول: بأنه حكاية عن كلام الله أو عبارة عنه."},{"id":"wasitiyya:227","bookId":"wasitiyya","type":"section","seq":227,"chapter":"مقدمة المصنف","title":"172- بل إذا قرأه الناس أو كتبوه في المصاحف؛ لم يخرج بذلك عن أن يكون كلام الله حقيقة؛ فإن الكلام","page":"ج1 ص89","text":"بل إذا قرأه الناس أو كتبوه في المصاحف؛ لم يخرج بذلك عن أن يكون كلام الله حقيقة؛ فإن الكلام إنما يضاف حقيقة إلى من قاله مبتدئا، لا إلى من قاله مبلغا مؤديا."},{"id":"wasitiyya:228","bookId":"wasitiyya","type":"section","seq":228,"chapter":"مقدمة المصنف","title":"173- وهو كلام الله؛ حروفه ومعانيه؛ ليس كلام الله الحروف دون المعاني","page":"ج1 ص89","text":"وهو كلام الله؛ حروفه ومعانيه؛ ليس كلام الله الحروف دون المعاني، ولا المعاني دون الحروف.\n* * * *"},{"id":"wasitiyya:229","bookId":"wasitiyya","type":"section","seq":229,"chapter":"مقدمة المصنف","title":"الفصل الثاني: الإيمان بأن المؤمنين يرون ربهم يوم القيامة","page":"ج1 ص90","text":"• وقد دخل أيضا فيما ذكرناه من الإيمان به وبكتبه وبرسله:"},{"id":"wasitiyya:230","bookId":"wasitiyya","type":"section","seq":230,"chapter":"مقدمة المصنف","title":"174- الإيمان بأن المؤمنين يرونه يوم القيامة عيانا بأبصارهم","page":"ج1 ص90","text":"الإيمان بأن المؤمنين يرونه يوم القيامة عيانا بأبصارهم.\nكما يرون الشمس صحوا ليس دونها سحاب.\nوكما يرون القمر ليلة البدر، لا يضامون في رؤيته."},{"id":"wasitiyya:231","bookId":"wasitiyya","type":"section","seq":231,"chapter":"مقدمة المصنف","title":"175- يرونه سبحانه وهم في عرصات القيامة","page":"ج1 ص90","text":"يرونه سبحانه وهم في عرصات القيامة."},{"id":"wasitiyya:232","bookId":"wasitiyya","type":"section","seq":232,"chapter":"مقدمة المصنف","title":"176- ثم يرونه بعد دخول الجنة كما يشاء الله سبحانه وتعالى","page":"ج1 ص90","text":"ثم يرونه بعد دخول الجنة كما يشاء الله سبحانه وتعالى.\n* * * *"},{"id":"wasitiyya:233","bookId":"wasitiyya","type":"section","seq":233,"chapter":"مقدمة المصنف","title":"الفصل الأول: الإيمان بكل ما أخبر به النبي صلى الله عليه وسلم مما يكون بعد الموت","page":"ج1 ص91","text":"الفصل الثاني: القيامة الكبرى وأهوالها.]"},{"id":"wasitiyya:234","bookId":"wasitiyya","type":"section","seq":234,"chapter":"مقدمة المصنف","title":"الفصل الأول: الإيمان بكل ما أخبر به النبي صلى الله عليه وسلم مما يكون بعد الموت","page":"ج1 ص93","text":"• ومن الإيمان باليوم الآخر:"},{"id":"wasitiyya:235","bookId":"wasitiyya","type":"section","seq":235,"chapter":"مقدمة المصنف","title":"177- الإيمان بكل ما أخبر به النبي صلى الله عليه وسلم مما يكون بعد الموت","page":"ج1 ص93","text":"الإيمان بكل ما أخبر به النبي صلى الله عليه وسلم مما يكون بعد الموت:"},{"id":"wasitiyya:236","bookId":"wasitiyya","type":"section","seq":236,"chapter":"مقدمة المصنف","title":"178- فيؤمنون","page":"ج1 ص93","text":"فيؤمنون:"},{"id":"wasitiyya:237","bookId":"wasitiyya","type":"section","seq":237,"chapter":"مقدمة المصنف","title":"1- فتنة القبر","page":"ج1 ص93","text":"] :\n- «بفتنة القبر» ."},{"id":"wasitiyya:238","bookId":"wasitiyya","type":"section","seq":238,"chapter":"مقدمة المصنف","title":"2- عذاب القبر ونعيمه","page":"ج1 ص93","text":"] :\n- «وبعذاب القبر وبنعيمه» ."},{"id":"wasitiyya:239","bookId":"wasitiyya","type":"section","seq":239,"chapter":"مقدمة المصنف","title":"179- فأما «الفتنة»","page":"ج1 ص93","text":"فأما «الفتنة» : فإن الناس يفتنون في قبورهم.\nفيقال للرجل: من ربك؟\nوما دينك؟\nومن نبيك؟\nف {يثبت الله الذين آمنوا بالقول الثابت} [إبراهيم: 27] .\n- فيقول «المؤمن» : الله ربي، والإسلام ديني، ومحمد صلى الله عليه وسلم نبيي.\n- وأما «المرتاب» فيقول: آه آه! لا أدري؛ سمعت الناس يقولون شيئا فقلته.\nفيضرب بمرزبة من حديد، فيصيح صيحة يسمعها كل شيء إلا الإنسان، ولو سمعها الإنسان؛ لصعق.\n* * * *"},{"id":"wasitiyya:240","bookId":"wasitiyya","type":"section","seq":240,"chapter":"مقدمة المصنف","title":"180- ثم بعد هذه الفتنة","page":"ج1 ص96","text":"ثم بعد هذه الفتنة: إما نعيم، وإما عذاب، إلى يوم القيامة الكبرى."},{"id":"wasitiyya:241","bookId":"wasitiyya","type":"section","seq":241,"chapter":"مقدمة المصنف","title":"1- إعادة الأرواح إلى الأجساد","page":"ج1 ص96","text":"] :"},{"id":"wasitiyya:242","bookId":"wasitiyya","type":"section","seq":242,"chapter":"مقدمة المصنف","title":"181- فتعاد «الأرواح إلى الأجساد»","page":"ج1 ص96","text":"فتعاد «الأرواح إلى الأجساد» ."},{"id":"wasitiyya:243","bookId":"wasitiyya","type":"section","seq":243,"chapter":"مقدمة المصنف","title":"182- فتقوم القيامة التي أخبر الله تعالى بها في كتابه","page":"ج1 ص96","text":"فتقوم القيامة التي أخبر الله تعالى بها في كتابه، على لسان رسوله صلى الله عليه وسلم، وأجمع عليها المسلمون."},{"id":"wasitiyya:244","bookId":"wasitiyya","type":"section","seq":244,"chapter":"مقدمة المصنف","title":"2- قيام الناس من قبورهم","page":"ج1 ص96","text":"] :"},{"id":"wasitiyya:245","bookId":"wasitiyya","type":"section","seq":245,"chapter":"مقدمة المصنف","title":"183- «فيقوم الناس من قبورهم» لرب العالمين","page":"ج1 ص96","text":"«فيقوم الناس من قبورهم» لرب العالمين، حفاة عراة غرلا.\n* * * *"},{"id":"wasitiyya:246","bookId":"wasitiyya","type":"section","seq":246,"chapter":"مقدمة المصنف","title":"3- دنو الشمس","page":"ج1 ص96","text":"] :"},{"id":"wasitiyya:247","bookId":"wasitiyya","type":"section","seq":247,"chapter":"مقدمة المصنف","title":"184- وتدنو منهم الشمس","page":"ج1 ص96","text":"وتدنو منهم الشمس.\n* * * *"},{"id":"wasitiyya:248","bookId":"wasitiyya","type":"section","seq":248,"chapter":"مقدمة المصنف","title":"4- العرق","page":"ج1 ص96","text":"] :"},{"id":"wasitiyya:249","bookId":"wasitiyya","type":"section","seq":249,"chapter":"مقدمة المصنف","title":"185- ويلجمهم العرق","page":"ج1 ص96","text":"ويلجمهم العرق.\n* * * *"},{"id":"wasitiyya:250","bookId":"wasitiyya","type":"section","seq":250,"chapter":"مقدمة المصنف","title":"5- نصب الموازين","page":"ج1 ص96","text":"] :"},{"id":"wasitiyya:251","bookId":"wasitiyya","type":"section","seq":251,"chapter":"مقدمة المصنف","title":"186- وتنصب الموازين","page":"ج1 ص96","text":"وتنصب الموازين، فيوزن فيها أعمال العباد.\n{فمن ثقلت موازينه فأولئك هم المفلحون • ومن خفت موازينه فأولئك الذين خسروا أنفسهم في جهنم خالدون} [المؤمنون: 102 - 103] ."},{"id":"wasitiyya:252","bookId":"wasitiyya","type":"section","seq":252,"chapter":"مقدمة المصنف","title":"6- نشر الدواوين","page":"ج1 ص97","text":"] :"},{"id":"wasitiyya:253","bookId":"wasitiyya","type":"section","seq":253,"chapter":"مقدمة المصنف","title":"187- وتنشر الدواوين","page":"ج1 ص97","text":"وتنشر الدواوين، وهي صحائف الأعمال.\n- فآخذ كتابه بيمينه.\n- وآخذ كتابه بشماله.\n- أو من وراء ظهره."},{"id":"wasitiyya:254","bookId":"wasitiyya","type":"section","seq":254,"chapter":"مقدمة المصنف","title":"188- كما قال سبحانه وتعالى","page":"ج1 ص97","text":"كما قال سبحانه وتعالى: {وكل إنسان ألزمناه طائره في عنقه ونخرج له يوم القيامة كتابا يلقاه منشورا • اقرأ كتابك كفى بنفسك اليوم عليك حسيبا} [الإسراء: 13 - 14] .\n* * * *"},{"id":"wasitiyya:255","bookId":"wasitiyya","type":"section","seq":255,"chapter":"مقدمة المصنف","title":"7- الحساب","page":"ج1 ص97","text":"] :"},{"id":"wasitiyya:256","bookId":"wasitiyya","type":"section","seq":256,"chapter":"مقدمة المصنف","title":"189- ويحاسب الله الخلق","page":"ج1 ص97","text":"ويحاسب الله الخلق."},{"id":"wasitiyya:257","bookId":"wasitiyya","type":"section","seq":257,"chapter":"مقدمة المصنف","title":"190- ويخلو بعبده المؤمن","page":"ج1 ص97","text":"ويخلو بعبده المؤمن، فيقرره بذنوبه كما وصف ذلك في الكتاب والسنة."},{"id":"wasitiyya:258","bookId":"wasitiyya","type":"section","seq":258,"chapter":"مقدمة المصنف","title":"191- وأما الكفار؛ فلا يحاسبون محاسبة من توزن حسناته — وسيئاته فإنهم لا حسنات لهم","page":"ج1 ص97","text":"وأما الكفار؛ فلا يحاسبون محاسبة من توزن حسناته\nوسيئاته فإنهم لا حسنات لهم، ولكن تعد أعمالهم، وتحصى فيوقفون عليها، ويقررون بها، ويجزون بها.\n* * * *"},{"id":"wasitiyya:259","bookId":"wasitiyya","type":"section","seq":259,"chapter":"مقدمة المصنف","title":"8- الحوض المورود","page":"ج1 ص98","text":"] :"},{"id":"wasitiyya:260","bookId":"wasitiyya","type":"section","seq":260,"chapter":"مقدمة المصنف","title":"192- وفي عرصة القيامة","page":"ج1 ص98","text":"وفي عرصة القيامة: «الحوض المورود لمحمد صلى الله عليه وسلم» ."},{"id":"wasitiyya:261","bookId":"wasitiyya","type":"section","seq":261,"chapter":"مقدمة المصنف","title":"193- ماؤه","page":"ج1 ص98","text":"ماؤه: أشد بياضا من اللبن وأحلى من العسل."},{"id":"wasitiyya:262","bookId":"wasitiyya","type":"section","seq":262,"chapter":"مقدمة المصنف","title":"194- آنيته","page":"ج1 ص98","text":"آنيته: عدد نجوم السماء."},{"id":"wasitiyya:263","bookId":"wasitiyya","type":"section","seq":263,"chapter":"مقدمة المصنف","title":"195- طوله","page":"ج1 ص98","text":"طوله: شهر، وعرضه: شهر."},{"id":"wasitiyya:264","bookId":"wasitiyya","type":"section","seq":264,"chapter":"مقدمة المصنف","title":"196- من شرب منه شربة؛ لم يظمأ بعدها أبدا","page":"ج1 ص98","text":"من شرب منه شربة؛ لم يظمأ بعدها أبدا.\n* * * *"},{"id":"wasitiyya:265","bookId":"wasitiyya","type":"section","seq":265,"chapter":"مقدمة المصنف","title":"9- الصراط","page":"ج1 ص98","text":"] :"},{"id":"wasitiyya:266","bookId":"wasitiyya","type":"section","seq":266,"chapter":"مقدمة المصنف","title":"197- «والصراط» منصوب على متن جهنم","page":"ج1 ص98","text":"«والصراط» منصوب على متن جهنم."},{"id":"wasitiyya:267","bookId":"wasitiyya","type":"section","seq":267,"chapter":"مقدمة المصنف","title":"198- وهو الجسر الذي بين الجنة والنار","page":"ج1 ص98","text":"وهو الجسر الذي بين الجنة والنار."},{"id":"wasitiyya:268","bookId":"wasitiyya","type":"section","seq":268,"chapter":"مقدمة المصنف","title":"199- يمر الناس عليه على قدر أعمالهم","page":"ج1 ص98","text":"يمر الناس عليه على قدر أعمالهم:\n- فمنهم من يمر كلمح البصر.\n- ومنهم من يمر كالبرق.\n- ومنهم من يمر كالريح.\n- ومنهم من يمر كالفرس الجواد.\n- ومنهم من يمر كركاب الإبل.\n- ومنهم من يعدو عدوا.\n- ومنهم من يمشي مشيا.\n- ومنهم من يزحف زحفا.\n- ومنهم من يخطف فيلقى في جهنم؛ فإن الجسر عليه كلاليب تخطف الناس بأعمالهم."},{"id":"wasitiyya:269","bookId":"wasitiyya","type":"section","seq":269,"chapter":"مقدمة المصنف","title":"200- فمن مر على الصراط؛ دخل الجنة","page":"ج1 ص99","text":"فمن مر على الصراط؛ دخل الجنة."},{"id":"wasitiyya:270","bookId":"wasitiyya","type":"section","seq":270,"chapter":"مقدمة المصنف","title":"201- فإذا عبروا عليه؛ وقفوا على قنطرة بين الجنة والنار؛ فيقتص لبعضهم من بعض","page":"ج1 ص99","text":"فإذا عبروا عليه؛ وقفوا على قنطرة بين الجنة والنار؛ فيقتص لبعضهم من بعض، فإذا هذبوا ونقوا؛ أذن لهم في دخول الجنة.\n* * * *"},{"id":"wasitiyya:271","bookId":"wasitiyya","type":"section","seq":271,"chapter":"مقدمة المصنف","title":"10- دخول الجنة","page":"ج1 ص99","text":"] :"},{"id":"wasitiyya:272","bookId":"wasitiyya","type":"section","seq":272,"chapter":"مقدمة المصنف","title":"202- وأول من يستفتح باب الجنة","page":"ج1 ص99","text":"وأول من يستفتح باب الجنة: محمد صلى الله عليه وسلم."},{"id":"wasitiyya:273","bookId":"wasitiyya","type":"section","seq":273,"chapter":"مقدمة المصنف","title":"203- وأول من يدخل الجنة من الأمم","page":"ج1 ص99","text":"وأول من يدخل الجنة من الأمم: أمته صلى الله عليه وسلم.\n* * * *"},{"id":"wasitiyya:274","bookId":"wasitiyya","type":"section","seq":274,"chapter":"مقدمة المصنف","title":"11- الشفاعة","page":"ج1 ص99","text":"] :"},{"id":"wasitiyya:275","bookId":"wasitiyya","type":"section","seq":275,"chapter":"مقدمة المصنف","title":"204- وله صلى الله عليه وسلم في القيامة ثلاث شفاعات","page":"ج1 ص99","text":"وله صلى الله عليه وسلم في القيامة ثلاث شفاعات:"},{"id":"wasitiyya:276","bookId":"wasitiyya","type":"section","seq":276,"chapter":"مقدمة المصنف","title":"205- أما الشفاعة الأولى","page":"ج1 ص99","text":"أما الشفاعة الأولى: فيشفع في أهل الموقف، حتى يقضى\nبينهم بعد أن يتراجع الأنبياء - آدم ونوح وإبراهيم وموسى وعيسى ابن مريم - الشفاعة حتى تنتهي إليه."},{"id":"wasitiyya:277","bookId":"wasitiyya","type":"section","seq":277,"chapter":"مقدمة المصنف","title":"206- وأما الشفاعة الثانية","page":"ج1 ص100","text":"وأما الشفاعة الثانية: فيشفع في أهل الجنة أن يدخلوا الجنة.\nوهاتان الشفاعتان خاصتان له."},{"id":"wasitiyya:278","bookId":"wasitiyya","type":"section","seq":278,"chapter":"مقدمة المصنف","title":"207- وأما الشفاعة الثالثة","page":"ج1 ص100","text":"وأما الشفاعة الثالثة: فيشفع فيمن استحق النار.\nوهذه الشفاعة له ولسائر النبيين والصديقين وغيرهم.\n- يشفع فيمن استحق النار أن لا يدخلها.\n- ويشفع فيمن دخلها أن يخرج منها."},{"id":"wasitiyya:279","bookId":"wasitiyya","type":"section","seq":279,"chapter":"مقدمة المصنف","title":"208- ويخرج الله تعالى من النار أقواما بغير شفاعة","page":"ج1 ص100","text":"ويخرج الله تعالى من النار أقواما بغير شفاعة، بل بفضل رحمته.\n* * * *"},{"id":"wasitiyya:280","bookId":"wasitiyya","type":"section","seq":280,"chapter":"مقدمة المصنف","title":"209- ويبقى في الجنة فضل عمن دخلها من أهل الدنيا","page":"ج1 ص100","text":"ويبقى في الجنة فضل عمن دخلها من أهل الدنيا."},{"id":"wasitiyya:281","bookId":"wasitiyya","type":"section","seq":281,"chapter":"مقدمة المصنف","title":"210- فينشئ الله لها أقواما","page":"ج1 ص100","text":"فينشئ الله لها أقواما، فيدخلهم الجنة.\n* * * *"},{"id":"wasitiyya:282","bookId":"wasitiyya","type":"section","seq":282,"chapter":"مقدمة المصنف","title":"211- وأصناف ما تتضمنه الدار الآخرة من","page":"ج1 ص100","text":"وأصناف ما تتضمنه الدار الآخرة من: الحساب، والعقاب والثواب، والجنة والنار."},{"id":"wasitiyya:283","bookId":"wasitiyya","type":"section","seq":283,"chapter":"مقدمة المصنف","title":"212- وتفاصيل ذلك مذكورة في","page":"ج1 ص101","text":"وتفاصيل ذلك مذكورة في:\n- الكتب المنزلة من السماء.\n- والأثارة من العلم؛ المأثورة عن الأنبياء."},{"id":"wasitiyya:284","bookId":"wasitiyya","type":"section","seq":284,"chapter":"مقدمة المصنف","title":"213- وفي العلم الموروث عن النبي محمد صلى الله عليه وسلم من ذلك؛ ما يشفي ويكفي","page":"ج1 ص101","text":"وفي العلم الموروث عن النبي محمد صلى الله عليه وسلم من ذلك؛ ما يشفي ويكفي، فمن ابتغاه وجده.\n* * * *"},{"id":"wasitiyya:285","bookId":"wasitiyya","type":"section","seq":285,"chapter":"مقدمة المصنف","title":"الفصل الأول: الدرجة الأولى من درجات الإيمان بالقدر","page":"ج1 ص102","text":"الفصل الثاني: الدرجة الثانية من درجات الإيمان بالقدر.]"},{"id":"wasitiyya:286","bookId":"wasitiyya","type":"section","seq":286,"chapter":"مقدمة المصنف","title":"الفصل الأول: الدرجة الأولى من درجات الإيمان بالقدر","page":"ج1 ص103","text":"• وتؤمن الفرقة الناجية أهل السنة والجماعة «بالقدر خيره وشره» ."},{"id":"wasitiyya:287","bookId":"wasitiyya","type":"section","seq":287,"chapter":"مقدمة المصنف","title":"214- والإيمان بالقدر على درجتين","page":"ج1 ص103","text":"والإيمان بالقدر على درجتين، كل درجة تتضمن شيئين."},{"id":"wasitiyya:288","bookId":"wasitiyya","type":"section","seq":288,"chapter":"مقدمة المصنف","title":"215- فالدرجة الأولى","page":"ج1 ص103","text":"فالدرجة الأولى: الإيمان:\n(1) بأن الله تعالى علم ما الخلق عاملون بعلمه القديم الذي هو موصوف به أزلا وأبدا.\nوعلم: جميع أحوالهم، من الطاعات والمعاصي والأرزاق والآجال.\n(2) ثم كتب الله تعالى في اللوح المحفوظ مقادير الخلائق."},{"id":"wasitiyya:289","bookId":"wasitiyya","type":"section","seq":289,"chapter":"مقدمة المصنف","title":"216- فأول ما خلق الله القلم؛ قال له","page":"ج1 ص103","text":"فأول ما خلق الله القلم؛ قال له: اكتب! قال: ما أكتب؟ قال: اكتب ما هو كائن إلى يوم القيامة."},{"id":"wasitiyya:290","bookId":"wasitiyya","type":"section","seq":290,"chapter":"مقدمة المصنف","title":"217- فما أصاب الإنسان لم يكن ليخطئه","page":"ج1 ص103","text":"فما أصاب الإنسان لم يكن ليخطئه، وما أخطأه لم يكن ليصيبه، جفت الأقلام وطويت الصحف."},{"id":"wasitiyya:291","bookId":"wasitiyya","type":"section","seq":291,"chapter":"مقدمة المصنف","title":"218- كما قال سبحانه وتعالى","page":"ج1 ص105","text":"كما قال سبحانه وتعالى: {ألم تعلم أن الله يعلم ما في السماء والأرض إن ذلك في كتاب إن ذلك على الله يسير} [الحج: 70] ."},{"id":"wasitiyya:292","bookId":"wasitiyya","type":"section","seq":292,"chapter":"مقدمة المصنف","title":"219- وقال","page":"ج1 ص105","text":"وقال: {ما أصاب من مصيبة في الأرض ولا في أنفسكم إلا في كتاب من قبل أن نبرأها إن ذلك على الله يسير} [الحديد: 22] ."},{"id":"wasitiyya:293","bookId":"wasitiyya","type":"section","seq":293,"chapter":"مقدمة المصنف","title":"220- وهذا التقدير التابع لعلمه سبحانه يكون في مواضع جملة وتفصيلا","page":"ج1 ص105","text":"وهذا التقدير التابع لعلمه سبحانه يكون في مواضع جملة وتفصيلا."},{"id":"wasitiyya:294","bookId":"wasitiyya","type":"section","seq":294,"chapter":"مقدمة المصنف","title":"221- فقد كتب في اللوح المحفوظ ما شاء","page":"ج1 ص105","text":"فقد كتب في اللوح المحفوظ ما شاء."},{"id":"wasitiyya:295","bookId":"wasitiyya","type":"section","seq":295,"chapter":"مقدمة المصنف","title":"222- فإذا خلق جسد الجنين قبل نفخ الروح فيه؛ بعث إليه ملكا فيؤمر بأربع كلمات","page":"ج1 ص105","text":"فإذا خلق جسد الجنين قبل نفخ الروح فيه؛ بعث إليه ملكا فيؤمر بأربع كلمات، فيقال: اكتب رزقه وأجله وعمله وشقي أو سعيد، ونحو ذلك."},{"id":"wasitiyya:296","bookId":"wasitiyya","type":"section","seq":296,"chapter":"مقدمة المصنف","title":"223- فهذا القدر قد كان ينكره غلاة «القدرية» قديما","page":"ج1 ص105","text":"فهذا القدر قد كان ينكره غلاة «القدرية» قديما، ومنكروه اليوم قليل.\n* * * *"},{"id":"wasitiyya:297","bookId":"wasitiyya","type":"section","seq":297,"chapter":"مقدمة المصنف","title":"224- وأما الدرجة الثانية","page":"ج1 ص106","text":"وأما الدرجة الثانية: فهي:\n- مشيئة الله تعالى النافذة، وقدرته الشاملة."},{"id":"wasitiyya:298","bookId":"wasitiyya","type":"section","seq":298,"chapter":"مقدمة المصنف","title":"225- وهو الإيمان بأن ما شاء الله كان","page":"ج1 ص106","text":"وهو الإيمان بأن ما شاء الله كان، وما لم يشأ لم يكن."},{"id":"wasitiyya:299","bookId":"wasitiyya","type":"section","seq":299,"chapter":"مقدمة المصنف","title":"226- وأنه ما في السماوات والأرض","page":"ج1 ص106","text":"وأنه ما في السماوات والأرض، من حركة ولا سكون إلا بمشيئة الله سبحانه، لا يكون في ملكه إلا ما يريد."},{"id":"wasitiyya:300","bookId":"wasitiyya","type":"section","seq":300,"chapter":"مقدمة المصنف","title":"227- وأنه سبحانه وتعالى على كل شيء قدير من الموجودات والمعدومات","page":"ج1 ص106","text":"وأنه سبحانه وتعالى على كل شيء قدير من الموجودات والمعدومات."},{"id":"wasitiyya:301","bookId":"wasitiyya","type":"section","seq":301,"chapter":"مقدمة المصنف","title":"228- فما من مخلوق في الأرض ولا في السماء إلا الله خالقه سبحانه لا خالق غيره","page":"ج1 ص106","text":"فما من مخلوق في الأرض ولا في السماء إلا الله خالقه سبحانه لا خالق غيره، ولا رب سواه."},{"id":"wasitiyya:302","bookId":"wasitiyya","type":"section","seq":302,"chapter":"مقدمة المصنف","title":"لا تعارض بين القدر والشرع ولا بين تقدير الله للمعاصي وبغضه لها","page":"ج1 ص106","text":"] :"},{"id":"wasitiyya:303","bookId":"wasitiyya","type":"section","seq":303,"chapter":"مقدمة المصنف","title":"229- وقد أمر العباد بطاعته وطاعة رسله","page":"ج1 ص106","text":"وقد أمر العباد بطاعته وطاعة رسله، ونهاهم عن معصيته."},{"id":"wasitiyya:304","bookId":"wasitiyya","type":"section","seq":304,"chapter":"مقدمة المصنف","title":"230- وهو سبحانه يحب المتقين والمحسنين والمقسطين","page":"ج1 ص106","text":"وهو سبحانه يحب المتقين والمحسنين والمقسطين."},{"id":"wasitiyya:305","bookId":"wasitiyya","type":"section","seq":305,"chapter":"مقدمة المصنف","title":"231- ويرضى عن الذين آمنوا وعملوا الصالحات","page":"ج1 ص107","text":"ويرضى عن الذين آمنوا وعملوا الصالحات، ولا يحب الكافرين، ولا يرضى عن القوم الفاسقين، ولا يأمر بالفحشاء."},{"id":"wasitiyya:306","bookId":"wasitiyya","type":"section","seq":306,"chapter":"مقدمة المصنف","title":"232- ولا يرضى لعباده الكفر","page":"ج1 ص107","text":"ولا يرضى لعباده الكفر، ولا يحب الفساد."},{"id":"wasitiyya:307","bookId":"wasitiyya","type":"section","seq":307,"chapter":"مقدمة المصنف","title":"إثبات القدر لا ينافي إسناد أفعال العباد إليهم حقيقة وأنهم يفعلونها باختيارهم","page":"ج1 ص107","text":"] :"},{"id":"wasitiyya:308","bookId":"wasitiyya","type":"section","seq":308,"chapter":"مقدمة المصنف","title":"233- والعباد فاعلون حقيقة","page":"ج1 ص107","text":"والعباد فاعلون حقيقة، والله خالق أفعالهم."},{"id":"wasitiyya:309","bookId":"wasitiyya","type":"section","seq":309,"chapter":"مقدمة المصنف","title":"234- والعبد هو","page":"ج1 ص107","text":"والعبد هو: المؤمن والكافر، والبر والفاجر، والمصلي والصائم."},{"id":"wasitiyya:310","bookId":"wasitiyya","type":"section","seq":310,"chapter":"مقدمة المصنف","title":"235- وللعباد قدرة على أعمالهم","page":"ج1 ص107","text":"وللعباد قدرة على أعمالهم، وإرادة، والله خالقهم وخالق قدرتهم وإرادتهم."},{"id":"wasitiyya:311","bookId":"wasitiyya","type":"section","seq":311,"chapter":"مقدمة المصنف","title":"236- كما قال تعالى","page":"ج1 ص107","text":"كما قال تعالى: {لمن شاء منكم أن يستقيم • وما تشاءون إلا أن يشاء الله رب العالمين} [التكوير: 28 - 29] ."},{"id":"wasitiyya:312","bookId":"wasitiyya","type":"section","seq":312,"chapter":"مقدمة المصنف","title":"237- وهذه الدرجة من القدر","page":"ج1 ص107","text":"وهذه الدرجة من القدر، يكذب بها عامة «القدرية» ، الذين سماهم النبي صلى الله عليه وسلم: «مجوس هذه الأمة» ."},{"id":"wasitiyya:313","bookId":"wasitiyya","type":"section","seq":313,"chapter":"مقدمة المصنف","title":"238- ويغلو فيها قوم من أهل الإثبات","page":"ج1 ص108","text":"ويغلو فيها قوم من أهل الإثبات، حتى يسلبوا العبد قدرته واختياره، ويخرجون عن أفعال الله وأحكامه؛ حكمها ومصالحها.\n* * * *"},{"id":"wasitiyya:314","bookId":"wasitiyya","type":"section","seq":314,"chapter":"مقدمة المصنف","title":"الفصل الأول: الدين والإيمان قول وعمل","page":"ج1 ص111","text":"• ومن أصول الفرقة الناجية:"},{"id":"wasitiyya:315","bookId":"wasitiyya","type":"section","seq":315,"chapter":"مقدمة المصنف","title":"239- أن الدين والإيمان","page":"ج1 ص111","text":"أن الدين والإيمان: قول، وعمل.\n- قول: القلب، واللسان.\n- وعمل: القلب، واللسان، والجوارح."},{"id":"wasitiyya:316","bookId":"wasitiyya","type":"section","seq":316,"chapter":"مقدمة المصنف","title":"240- وأن الإيمان","page":"ج1 ص111","text":"وأن الإيمان: يزيد بالطاعة، وينقص بالمعصية."},{"id":"wasitiyya:317","bookId":"wasitiyya","type":"section","seq":317,"chapter":"مقدمة المصنف","title":"أهل السنة لا يكفرون أهل القبلة بمطلق المعاصي والكبائر","page":"ج1 ص111","text":"] :"},{"id":"wasitiyya:318","bookId":"wasitiyya","type":"section","seq":318,"chapter":"مقدمة المصنف","title":"241- وهم مع ذلك","page":"ج1 ص111","text":"وهم مع ذلك، لا يكفرون أهل القبلة بمطلق المعاصي والكبائر، كما تفعله «الخوارج» ، بل الأخوة الإيمانية ثابتة مع المعاصي."},{"id":"wasitiyya:319","bookId":"wasitiyya","type":"section","seq":319,"chapter":"مقدمة المصنف","title":"242- كما قال سبحانه وتعالى في آية القصاص","page":"ج1 ص111","text":"كما قال سبحانه وتعالى في آية القصاص: {فمن عفي له من أخيه شيء} [البقرة: 178] ."},{"id":"wasitiyya:320","bookId":"wasitiyya","type":"section","seq":320,"chapter":"مقدمة المصنف","title":"243- وقال سبحانه","page":"ج1 ص111","text":"وقال سبحانه: {وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما فإن بغت إحداهما على الأخرى فقاتلوا التي تبغي حتى تفيء إلى أمر الله فإن فاءت فأصلحوا بينهما بالعدل وأقسطوا إن الله يحب المقسطين • إنما المؤمنون إخوة} [الحجرات: 9 - 10] ."},{"id":"wasitiyya:321","bookId":"wasitiyya","type":"section","seq":321,"chapter":"مقدمة المصنف","title":"244- ولا يسلبون الفاسق الملي اسم الإيمان بالكلية","page":"ج1 ص113","text":"ولا يسلبون الفاسق الملي اسم الإيمان بالكلية، ولا يخلدونه في النار، كما تقوله «المعتزلة» ، بل الفاسق يدخل في اسم الإيمان."},{"id":"wasitiyya:322","bookId":"wasitiyya","type":"section","seq":322,"chapter":"مقدمة المصنف","title":"245- في مثل قوله تعالى","page":"ج1 ص113","text":"في مثل قوله تعالى: {فتحرير رقبة مؤمنة} [النساء: 92] ."},{"id":"wasitiyya:323","bookId":"wasitiyya","type":"section","seq":323,"chapter":"مقدمة المصنف","title":"246- وقد لا يدخل في اسم الإيمان المطلق","page":"ج1 ص113","text":"وقد لا يدخل في اسم الإيمان المطلق."},{"id":"wasitiyya:324","bookId":"wasitiyya","type":"section","seq":324,"chapter":"مقدمة المصنف","title":"247- كما في قوله تعالى","page":"ج1 ص113","text":"كما في قوله تعالى: {إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم} ."},{"id":"wasitiyya:325","bookId":"wasitiyya","type":"section","seq":325,"chapter":"مقدمة المصنف","title":"248- وقول النبي صلى الله عليه وسلم","page":"ج1 ص113","text":"وقول النبي صلى الله عليه وسلم: «لا يزني الزاني حين يزني وهو مؤمن، ولا يسرق حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، ولا ينتهب نهبة ذات شرف يرفع الناس إليه فيها أبصارهم حين ينتهبها وهو مؤمن» ."},{"id":"wasitiyya:326","bookId":"wasitiyya","type":"section","seq":326,"chapter":"مقدمة المصنف","title":"249- ويقولون","page":"ج1 ص113","text":"ويقولون: هو مؤمن ناقص الإيمان، أو مؤمن بإيمانه، فاسق بكبيرته؛ فلا يعطى الاسم المطلق، ولا يسلب مطلق الاسم.\n* * * *"},{"id":"wasitiyya:327","bookId":"wasitiyya","type":"section","seq":327,"chapter":"مقدمة المصنف","title":"الفصل الثاني: خلاصة مذهب أهل السنة في أصحاب رسول الله صلى الله عليه وسلم","page":"ج1 ص114","text":"• ومن أصول أهل السنة والجماعة:"},{"id":"wasitiyya:328","bookId":"wasitiyya","type":"section","seq":328,"chapter":"مقدمة المصنف","title":"250- سلامة قلوبهم وألسنتهم لأصحاب محمد الله صلى الله عليه وسلم","page":"ج1 ص114","text":"سلامة قلوبهم وألسنتهم لأصحاب محمد الله صلى الله عليه وسلم."},{"id":"wasitiyya:329","bookId":"wasitiyya","type":"section","seq":329,"chapter":"مقدمة المصنف","title":"251- كما وصفهم الله به في قوله","page":"ج1 ص114","text":"كما وصفهم الله به في قوله: {والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان ولا تجعل في قلوبنا غلا للذين آمنوا ربنا إنك رءوف رحيم} [الحشر: 10] ."},{"id":"wasitiyya:330","bookId":"wasitiyya","type":"section","seq":330,"chapter":"مقدمة المصنف","title":"252- وطاعة للنبي صلى الله عليه وسلم في قوله","page":"ج1 ص114","text":"وطاعة للنبي صلى الله عليه وسلم في قوله: «لا تسبوا أصحابي؛ فوالذي نفسي بيده؛ لو أن أحدكم أنفق مثل أحد ذهبا؛ ما بلغ مد أحدهم ولا نصيفه» ."},{"id":"wasitiyya:331","bookId":"wasitiyya","type":"section","seq":331,"chapter":"مقدمة المصنف","title":"فضائل الصحابة ومراتبهم وتفاضلهم وموقف أهل السنة والجماعة من ذلك","page":"ج1 ص114","text":"] :"},{"id":"wasitiyya:332","bookId":"wasitiyya","type":"section","seq":332,"chapter":"مقدمة المصنف","title":"253- ويقبلون ما جاء به الكتاب أو السنة أو الإجماع","page":"ج1 ص114","text":"ويقبلون ما جاء به الكتاب أو السنة أو الإجماع، من فضائلهم ومراتبهم."},{"id":"wasitiyya:333","bookId":"wasitiyya","type":"section","seq":333,"chapter":"مقدمة المصنف","title":"254- فيفضلون من أنفق من قبل الفتح - وهو صلح الحديبية - وقاتل على من أنفق من بعده وقاتل","page":"ج1 ص114","text":"فيفضلون من أنفق من قبل الفتح - وهو صلح الحديبية - وقاتل على من أنفق من بعده وقاتل."},{"id":"wasitiyya:334","bookId":"wasitiyya","type":"section","seq":334,"chapter":"مقدمة المصنف","title":"255- ويقدمون المهاجرين على الأنصار","page":"ج1 ص115","text":"ويقدمون المهاجرين على الأنصار."},{"id":"wasitiyya:335","bookId":"wasitiyya","type":"section","seq":335,"chapter":"مقدمة المصنف","title":"256- ويؤمنون","page":"ج1 ص115","text":"ويؤمنون: بأن الله تعالى قال لأهل بدر - وكانوا ثلاثمائة وبضعة عشر -: «اعملوا ما شئتم فقد غفرت لكم» ."},{"id":"wasitiyya:336","bookId":"wasitiyya","type":"section","seq":336,"chapter":"مقدمة المصنف","title":"257- وبأنه","page":"ج1 ص115","text":"وبأنه: «لا يدخل النار أحد بايع تحت الشجرة» ؛ كما أخبر به النبي صلى الله عليه وسلم، بل قد رضي عنهم ورضوا عنه، وكانوا أكثر من ألف وأربعمائة."},{"id":"wasitiyya:337","bookId":"wasitiyya","type":"section","seq":337,"chapter":"مقدمة المصنف","title":"258- ويشهدون بالجنة لمن شهد له النبي صلى الله عليه وسلم؛ «كالعشرة»","page":"ج1 ص115","text":"ويشهدون بالجنة لمن شهد له النبي صلى الله عليه وسلم؛ «كالعشرة» .\n- «وكثابت بن قيس بن شماس» ، وغيرهم من الصحابة."},{"id":"wasitiyya:338","bookId":"wasitiyya","type":"section","seq":338,"chapter":"مقدمة المصنف","title":"259- ويقرون بما تواتر به النقل عن أمير المؤمنين علي بن أبي طالب رضي الله عنه وغيره؛ من أن","page":"ج1 ص116","text":"ويقرون بما تواتر به النقل عن أمير المؤمنين علي بن أبي طالب رضي الله عنه وغيره؛ من أن: خير هذه الأمة بعد نبيها: أبو بكر، ثم عمر، ويثلثون بعثمان، ويربعون بعلي رضي الله عنهم؛ كما دلت عليه الآثار."},{"id":"wasitiyya:339","bookId":"wasitiyya","type":"section","seq":339,"chapter":"مقدمة المصنف","title":"حكم تقديم علي رضي الله عنه على غيره من الخلفاء الأربعة في الخلافة","page":"ج1 ص116","text":"] :"},{"id":"wasitiyya:340","bookId":"wasitiyya","type":"section","seq":340,"chapter":"مقدمة المصنف","title":"260- وكما أجمعت الصحابة على تقديم عثمان في البيعة","page":"ج1 ص116","text":"وكما أجمعت الصحابة على تقديم عثمان في البيعة، مع أن بعض أهل السنة كانوا قد اختلفوا في عثمان وعلي بعد اتفاقهم على تقديم أبي بكر وعمر؛ أيهما أفضل؟\n- فقدم قوم عثمان، وسكتوا، أو ربعوا بعلي.\n- وقدم قوم عليا.\n- وقوم توقفوا.\nلكن استقر أمر أهل السنة على: تقديم عثمان، ثم علي."},{"id":"wasitiyya:341","bookId":"wasitiyya","type":"section","seq":341,"chapter":"مقدمة المصنف","title":"261- وإن كانت هذه المسألة - مسألة عثمان وعلي - ليست من الأصول التي يضلل المخالف فيها عند جمهور","page":"ج1 ص117","text":"وإن كانت هذه المسألة - مسألة عثمان وعلي - ليست من الأصول التي يضلل المخالف فيها عند جمهور أهل السنة."},{"id":"wasitiyya:342","bookId":"wasitiyya","type":"section","seq":342,"chapter":"مقدمة المصنف","title":"262- لكن المسألة التي يضلل المخالف فيها","page":"ج1 ص117","text":"لكن المسألة التي يضلل المخالف فيها: مسألة الخلافة."},{"id":"wasitiyya:343","bookId":"wasitiyya","type":"section","seq":343,"chapter":"مقدمة المصنف","title":"263- وذلك بأنهم يؤمنون","page":"ج1 ص117","text":"وذلك بأنهم يؤمنون: بأن الخليفة بعد رسول الله صلى الله عليه وسلم: أبو بكر، ثم عمر، ثم عثمان، ثم علي، رضي الله عنهم."},{"id":"wasitiyya:344","bookId":"wasitiyya","type":"section","seq":344,"chapter":"مقدمة المصنف","title":"264- ومن طعن في خلافة أحد من هؤلاء الأئمة؛ فهو أضل من حمار أهله","page":"ج1 ص117","text":"ومن طعن في خلافة أحد من هؤلاء الأئمة؛ فهو أضل من حمار أهله."},{"id":"wasitiyya:345","bookId":"wasitiyya","type":"section","seq":345,"chapter":"مقدمة المصنف","title":"مكانة أهل بيت رسول الله صلى الله عليه وسلم عند أهل السنة","page":"ج1 ص117","text":"] :"},{"id":"wasitiyya:346","bookId":"wasitiyya","type":"section","seq":346,"chapter":"مقدمة المصنف","title":"265- ويحبون أهل بيت رسول الله صلى الله عليه وسلم","page":"ج1 ص117","text":"ويحبون أهل بيت رسول الله صلى الله عليه وسلم، ويتولونهم."},{"id":"wasitiyya:347","bookId":"wasitiyya","type":"section","seq":347,"chapter":"مقدمة المصنف","title":"266- ويحفظون فيهم وصية رسول الله صلى الله عليه وسلم؛ حيث قال يوم غدير خم","page":"ج1 ص117","text":"ويحفظون فيهم وصية رسول الله صلى الله عليه وسلم؛ حيث قال يوم غدير خم: «أذكركم الله في أهل بيتي، أذكركم الله في أهل بيتي» ."},{"id":"wasitiyya:348","bookId":"wasitiyya","type":"section","seq":348,"chapter":"مقدمة المصنف","title":"267- وقال أيضا للعباس عمه؛ وقد شكا إليه أن بعض قريش يجفو بني هاشم؛ فقال","page":"ج1 ص117","text":"وقال أيضا للعباس عمه؛ وقد شكا إليه أن بعض قريش يجفو بني هاشم؛ فقال: «والذي نفسي بيده؛ لا يؤمنون حتى يحبوكم لله ولقرابتي» ."},{"id":"wasitiyya:349","bookId":"wasitiyya","type":"section","seq":349,"chapter":"مقدمة المصنف","title":"268- وقال","page":"ج1 ص118","text":"وقال: «إن الله اصطفى إسماعيل، واصطفى من بني إسماعيل كنانة، واصطفى من كنانة قريشا، واصطفى من قريش بني هاشم، واصطفاني من بني هاشم» ."},{"id":"wasitiyya:350","bookId":"wasitiyya","type":"section","seq":350,"chapter":"مقدمة المصنف","title":"مكانة أزواج رسول الله صلى الله عليه وسلم عند أهل السنة","page":"ج1 ص118","text":"] :"},{"id":"wasitiyya:351","bookId":"wasitiyya","type":"section","seq":351,"chapter":"مقدمة المصنف","title":"269- ويتولون أزواج رسول الله صلى الله عليه وسلم أمهات المؤمنين","page":"ج1 ص118","text":"ويتولون أزواج رسول الله صلى الله عليه وسلم أمهات المؤمنين."},{"id":"wasitiyya:352","bookId":"wasitiyya","type":"section","seq":352,"chapter":"مقدمة المصنف","title":"270- ويقرون","page":"ج1 ص118","text":"ويقرون: بأنهن أزواجه في الآخرة."},{"id":"wasitiyya:353","bookId":"wasitiyya","type":"section","seq":353,"chapter":"مقدمة المصنف","title":"271- خصوصا «خديجة» أم أكثر أولاده","page":"ج1 ص118","text":"خصوصا «خديجة» أم أكثر أولاده، وأول من آمن به وعاضده على أمره، وكان لها منه المنزلة العلية."},{"id":"wasitiyya:354","bookId":"wasitiyya","type":"section","seq":354,"chapter":"مقدمة المصنف","title":"272- «والصديقة بنت الصديق» التي قال فيها النبي صلى الله عليه وسلم","page":"ج1 ص118","text":"«والصديقة بنت الصديق» التي قال فيها النبي صلى الله عليه وسلم: «فضل عائشة على النساء كفضل الثريد على سائر الطعام» ."},{"id":"wasitiyya:355","bookId":"wasitiyya","type":"section","seq":355,"chapter":"مقدمة المصنف","title":"تبرؤ أهل السنة والجماعة مما يقوله المبتدعة في حق الصحابة وأهل البيت، والذب عنهم","page":"ج1 ص118","text":"] :"},{"id":"wasitiyya:356","bookId":"wasitiyya","type":"section","seq":356,"chapter":"مقدمة المصنف","title":"273- ويتبرؤون من","page":"ج1 ص118","text":"ويتبرؤون من:\n- طريقة «الروافض» الذين يبغضون الصحابة ويسبونهم.\n- وطريقة «النواصب» ، الذين يؤذون «أهل البيت» ، بقول أو عمل."},{"id":"wasitiyya:357","bookId":"wasitiyya","type":"section","seq":357,"chapter":"مقدمة المصنف","title":"منهج أهل السنة فيما شجر بين الصحابة","page":"ج1 ص119","text":"] :"},{"id":"wasitiyya:358","bookId":"wasitiyya","type":"section","seq":358,"chapter":"مقدمة المصنف","title":"274- ويمسكون عما شجر بين الصحابة","page":"ج1 ص119","text":"ويمسكون عما شجر بين الصحابة."},{"id":"wasitiyya:359","bookId":"wasitiyya","type":"section","seq":359,"chapter":"مقدمة المصنف","title":"275- ويقولون","page":"ج1 ص119","text":"ويقولون: إن هذه الآثار المروية في مساويهم:\nمنها: ما هو كذب.\nومنها: ما قد زيد فيه ونقص، وغير عن وجهه.\nوالصحيح منه: هم فيه معذورون:\n- إما مجتهدون مصيبون.\n- وإما مجتهدون مخطئون."},{"id":"wasitiyya:360","bookId":"wasitiyya","type":"section","seq":360,"chapter":"مقدمة المصنف","title":"276- وهم مع ذلك لا يعتقدون أن كل واحد من الصحابة معصوم عن كبائر الإثم وصغائره","page":"ج1 ص119","text":"وهم مع ذلك لا يعتقدون أن كل واحد من الصحابة معصوم عن كبائر الإثم وصغائره.\n- بل يجوز عليهم الذنوب في الجملة."},{"id":"wasitiyya:361","bookId":"wasitiyya","type":"section","seq":361,"chapter":"مقدمة المصنف","title":"من مناقب أصحاب رسول الله صلى الله عليه وسلم","page":"ج1 ص119","text":"] :"},{"id":"wasitiyya:362","bookId":"wasitiyya","type":"section","seq":362,"chapter":"مقدمة المصنف","title":"277- ولهم من السوابق والفضائل ما يوجب مغفرة ما يصدر منهم إن صدر","page":"ج1 ص119","text":"ولهم من السوابق والفضائل ما يوجب مغفرة ما يصدر منهم إن صدر."},{"id":"wasitiyya:363","bookId":"wasitiyya","type":"section","seq":363,"chapter":"مقدمة المصنف","title":"278- حتى إنه يغفر لهم من السيئات ما لا يغفر لمن بعدهم","page":"ج1 ص119","text":"حتى إنه يغفر لهم من السيئات ما لا يغفر لمن بعدهم، لأن لهم من الحسنات التي تمحو السيئات ما ليس لمن بعدهم."},{"id":"wasitiyya:364","bookId":"wasitiyya","type":"section","seq":364,"chapter":"مقدمة المصنف","title":"279- وقد ثبت بقول رسول الله صلى الله عليه وسلم","page":"ج1 ص120","text":"وقد ثبت بقول رسول الله صلى الله عليه وسلم: «إنهم خير القرون» ."},{"id":"wasitiyya:365","bookId":"wasitiyya","type":"section","seq":365,"chapter":"مقدمة المصنف","title":"280- وأن «المد من أحدهم إذا تصدق به؛ كان أفضل من جبل أحد ذهبا ممن بعدهم»","page":"ج1 ص120","text":"وأن «المد من أحدهم إذا تصدق به؛ كان أفضل من جبل أحد ذهبا ممن بعدهم» ."},{"id":"wasitiyya:366","bookId":"wasitiyya","type":"section","seq":366,"chapter":"مقدمة المصنف","title":"281- ثم إذا كان قد صدر عن أحدهم ذنب؛ فيكون قد تاب منه أو أتى بحسنات تمحوه","page":"ج1 ص120","text":"ثم إذا كان قد صدر عن أحدهم ذنب؛ فيكون قد تاب منه أو أتى بحسنات تمحوه، أو غفر له بفضل سابقته، أو بشفاعة محمد صلى الله عليه وسلم الذين هم أحق الناس بشفاعته. أو ابتلي ببلاء في الدنيا كفر به عنه."},{"id":"wasitiyya:367","bookId":"wasitiyya","type":"section","seq":367,"chapter":"مقدمة المصنف","title":"282- فإذا كان هذا في الذنوب المحققة؛ فكيف بالأمور التي كانوا فيها مجتهدين","page":"ج1 ص120","text":"فإذا كان هذا في الذنوب المحققة؛ فكيف بالأمور التي كانوا فيها مجتهدين: إن أصابوا؛ فلهم أجران، وإن أخطأوا؛ فلهم أجر واحد، والخطأ مغفور."},{"id":"wasitiyya:368","bookId":"wasitiyya","type":"section","seq":368,"chapter":"مقدمة المصنف","title":"283- ثم القدر الذي ينكر من فعل بعضهم قليل نزر مغمور في جنب فضائل القوم ومحاسنهم","page":"ج1 ص120","text":"ثم القدر الذي ينكر من فعل بعضهم قليل نزر مغمور في جنب فضائل القوم ومحاسنهم، من: الإيمان بالله ورسوله، والجهاد\nفي سبيله، والهجرة، والنصرة، والعلم النافع، والعمل الصالح."},{"id":"wasitiyya:369","bookId":"wasitiyya","type":"section","seq":369,"chapter":"مقدمة المصنف","title":"284- ومن نظر في سيرة القوم بعلم وبصيرة","page":"ج1 ص121","text":"ومن نظر في سيرة القوم بعلم وبصيرة، وما من الله به عليهم من الفضائل؛ علم يقينا أنهم خير الخلق بعد الأنبياء."},{"id":"wasitiyya:370","bookId":"wasitiyya","type":"section","seq":370,"chapter":"مقدمة المصنف","title":"285- لا كان ولا يكون مثلهم","page":"ج1 ص121","text":"لا كان ولا يكون مثلهم."},{"id":"wasitiyya:371","bookId":"wasitiyya","type":"section","seq":371,"chapter":"مقدمة المصنف","title":"286- وأنهم هم صفوة الصفوة من قرون هذه الأمة","page":"ج1 ص121","text":"وأنهم هم صفوة الصفوة من قرون هذه الأمة، التي هي خير الأمم وأكرمها على الله.\n* * * *"},{"id":"wasitiyya:372","bookId":"wasitiyya","type":"section","seq":372,"chapter":"مقدمة المصنف","title":"الفصل الثالث: التصديق بكرامات الأولياء","page":"ج1 ص122","text":"• ومن أصول أهل السنة:"},{"id":"wasitiyya:373","bookId":"wasitiyya","type":"section","seq":373,"chapter":"مقدمة المصنف","title":"287- التصديق بكرامات الأولياء","page":"ج1 ص122","text":"التصديق بكرامات الأولياء."},{"id":"wasitiyya:374","bookId":"wasitiyya","type":"section","seq":374,"chapter":"مقدمة المصنف","title":"288- وما يجري الله على أيديهم؛ من خوارق العادات","page":"ج1 ص122","text":"وما يجري الله على أيديهم؛ من خوارق العادات، في:\n- أنواع العلوم.\n- والمكاشفات.\n- وأنواع القدرة.\n- والتأثيرات.\n- وكالمأثور عن سالف الأمم، في «سورة الكهف» وغيرها.\n- وعن صدر هذه الأمة من الصحابة والتابعين وسائر قرون الأمة."},{"id":"wasitiyya:375","bookId":"wasitiyya","type":"section","seq":375,"chapter":"مقدمة المصنف","title":"289- وهي موجودة فيها إلى يوم القيامة","page":"ج1 ص122","text":"وهي موجودة فيها إلى يوم القيامة.\n* * * *"},{"id":"wasitiyya:376","bookId":"wasitiyya","type":"section","seq":376,"chapter":"مقدمة المصنف","title":"الفصل الأول: اتباع آثار رسول الله صلى الله عليه وسلم واتباع سبيل السابقين","page":"ج1 ص123","text":"الفصل الثاني: من خصالهم الحميدة.]"},{"id":"wasitiyya:377","bookId":"wasitiyya","type":"section","seq":377,"chapter":"مقدمة المصنف","title":"الفصل الأول: اتباع آثار رسول الله صلى الله عليه وسلم واتباع سبيل السابقين","page":"ج1 ص125","text":"• ثم من طريقة أهل السنة والجماعة:"},{"id":"wasitiyya:378","bookId":"wasitiyya","type":"section","seq":378,"chapter":"مقدمة المصنف","title":"290- اتباع","page":"ج1 ص125","text":"اتباع: آثار رسول الله صلى الله عليه وسلم باطنا وظاهرا."},{"id":"wasitiyya:379","bookId":"wasitiyya","type":"section","seq":379,"chapter":"مقدمة المصنف","title":"291- واتباع","page":"ج1 ص125","text":"واتباع: سبيل السابقين الأولين، من المهاجرين والأنصار."},{"id":"wasitiyya:380","bookId":"wasitiyya","type":"section","seq":380,"chapter":"مقدمة المصنف","title":"292- واتباع","page":"ج1 ص125","text":"واتباع: وصية رسول الله صلى الله عليه وسلم، حيث قال: «عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ، وإياكم ومحدثات الأمور فإن كل بدعة ضلالة» ."},{"id":"wasitiyya:381","bookId":"wasitiyya","type":"section","seq":381,"chapter":"مقدمة المصنف","title":"293- ويعلمون","page":"ج1 ص125","text":"ويعلمون: أن أصدق الكلام كلام الله، وخير الهدي هدي محمد صلى الله عليه وسلم."},{"id":"wasitiyya:382","bookId":"wasitiyya","type":"section","seq":382,"chapter":"مقدمة المصنف","title":"294- فيؤثرون","page":"ج1 ص127","text":"فيؤثرون: كلام الله على غيره من كلام أصناف الناس."},{"id":"wasitiyya:383","bookId":"wasitiyya","type":"section","seq":383,"chapter":"مقدمة المصنف","title":"لماذا سمي أهل الكتاب والسنة بهذا الاسم؟","page":"ج1 ص127","text":"] :"},{"id":"wasitiyya:384","bookId":"wasitiyya","type":"section","seq":384,"chapter":"مقدمة المصنف","title":"295- ويقدمون","page":"ج1 ص127","text":"ويقدمون: هدي محمد صلى الله عليه وسلم على هدي كل أحد.\nوبهذا سموا: «أهل الكتاب والسنة» ."},{"id":"wasitiyya:385","bookId":"wasitiyya","type":"section","seq":385,"chapter":"مقدمة المصنف","title":"لماذا سموا بأهل الجماعة؟","page":"ج1 ص127","text":"] :"},{"id":"wasitiyya:386","bookId":"wasitiyya","type":"section","seq":386,"chapter":"مقدمة المصنف","title":"296- وسموا «أهل الجماعة» ؛ لأن الجماعة هي الاجتماع","page":"ج1 ص127","text":"وسموا «أهل الجماعة» ؛ لأن الجماعة هي الاجتماع. وضدها الفرقة، وإن كان لفظ «الجماعة» قد صار اسما لنفس القوم المجتمعين."},{"id":"wasitiyya:387","bookId":"wasitiyya","type":"section","seq":387,"chapter":"مقدمة المصنف","title":"الإجماع هو الأصل الثالث","page":"ج1 ص127","text":"] :"},{"id":"wasitiyya:388","bookId":"wasitiyya","type":"section","seq":388,"chapter":"مقدمة المصنف","title":"297- والإجماع","page":"ج1 ص127","text":"والإجماع: هو الأصل الثالث؛ الذي يعتمد عليه في العلم والدين."},{"id":"wasitiyya:389","bookId":"wasitiyya","type":"section","seq":389,"chapter":"مقدمة المصنف","title":"298- وهم يزنون بهذه الأصول الثلاثة جميع ما عليه الناس من أقوال وأعمال باطنة أو ظاهرة","page":"ج1 ص127","text":"وهم يزنون بهذه الأصول الثلاثة جميع ما عليه الناس من أقوال وأعمال باطنة أو ظاهرة، مما له تعلق بالدين."},{"id":"wasitiyya:390","bookId":"wasitiyya","type":"section","seq":390,"chapter":"مقدمة المصنف","title":"299- والإجماع الذي ينضبط","page":"ج1 ص127","text":"والإجماع الذي ينضبط: هو ما كان عليه «السلف الصالح» ؛ إذ بعدهم كثر الاختلاف، وانتشرت الأمة.\n* * * *"},{"id":"wasitiyya:391","bookId":"wasitiyya","type":"section","seq":391,"chapter":"مقدمة المصنف","title":"فصل في بيان مكملات العقيدة من مكارم الأخلاق ومحاسن الأعمال التي يتحلى بها أهل السنة والجماعة","page":"ج1 ص128","text":"] :\n• ثم هم مع هذه الأصول:"},{"id":"wasitiyya:392","bookId":"wasitiyya","type":"section","seq":392,"chapter":"مقدمة المصنف","title":"300- يأمرون","page":"ج1 ص128","text":"يأمرون: بالمعروف، وينهون عن المنكر، على ما توجبه الشريعة."},{"id":"wasitiyya:393","bookId":"wasitiyya","type":"section","seq":393,"chapter":"مقدمة المصنف","title":"301- ويرون إقامة","page":"ج1 ص128","text":"ويرون إقامة: الحج، والجهاد، والجمع، والأعياد؛ مع الأمراء؛ أبرارا كانوا، أو فجارا."},{"id":"wasitiyya:394","bookId":"wasitiyya","type":"section","seq":394,"chapter":"مقدمة المصنف","title":"302- ويحافظون على","page":"ج1 ص128","text":"ويحافظون على: الجماعات."},{"id":"wasitiyya:395","bookId":"wasitiyya","type":"section","seq":395,"chapter":"مقدمة المصنف","title":"303- ويدينون","page":"ج1 ص128","text":"ويدينون: بالنصيحة للأمة."},{"id":"wasitiyya:396","bookId":"wasitiyya","type":"section","seq":396,"chapter":"مقدمة المصنف","title":"304- ويعتقدون","page":"ج1 ص128","text":"ويعتقدون:\n- معنى قوله صلى الله عليه وسلم: «المؤمن للمؤمن كالبنيان، يشد بعضه بعضا» وشبك بين أصابعه صلى الله عليه وسلم.\n- وقوله صلى الله عليه وسلم: «مثل المؤمنين في توادهم وتراحمهم وتعاطفهم؛ كمثل الجسد، إذا اشتكى منه عضو؛ تداعى له سائر الجسد بالحمى والسهر» ."},{"id":"wasitiyya:397","bookId":"wasitiyya","type":"section","seq":397,"chapter":"مقدمة المصنف","title":"305- ويأمرون","page":"ج1 ص129","text":"ويأمرون:\n- بالصبر على البلاء.\n- والشكر عند الرخاء.\n- والرضا بمر القضاء."},{"id":"wasitiyya:398","bookId":"wasitiyya","type":"section","seq":398,"chapter":"مقدمة المصنف","title":"306- ويدعون إلى","page":"ج1 ص129","text":"ويدعون إلى:\n- مكارم الأخلاق.\n- ومحاسن الأعمال."},{"id":"wasitiyya:399","bookId":"wasitiyya","type":"section","seq":399,"chapter":"مقدمة المصنف","title":"307- ويعتقدون","page":"ج1 ص129","text":"ويعتقدون: معنى قول النبي صلى الله عليه وسلم: «أكمل المؤمنين إيمانا أحسنهم خلقا» ."},{"id":"wasitiyya:400","bookId":"wasitiyya","type":"section","seq":400,"chapter":"مقدمة المصنف","title":"308- ويندبون إلى","page":"ج1 ص129","text":"ويندبون إلى:\n- أن تصل من قطعك.\n- وتعطي من حرمك.\n- وتعفو عمن ظلمك."},{"id":"wasitiyya:401","bookId":"wasitiyya","type":"section","seq":401,"chapter":"مقدمة المصنف","title":"309- ويأمرون","page":"ج1 ص130","text":"ويأمرون:\n- ببر الوالدين.\n- وصلة الأرحام.\n- وحسن الجوار.\n- والإحسان إلى: اليتامى، والمساكين، وابن السبيل.\n- والرفق بالمملوك."},{"id":"wasitiyya:402","bookId":"wasitiyya","type":"section","seq":402,"chapter":"مقدمة المصنف","title":"310- وينهون عن","page":"ج1 ص130","text":"وينهون عن:\n- الفخر، والخيلاء.\n- والبغي، والاستطالة على الخلق بحق أو بغير حق."},{"id":"wasitiyya:403","bookId":"wasitiyya","type":"section","seq":403,"chapter":"مقدمة المصنف","title":"311- ويأمرون","page":"ج1 ص130","text":"ويأمرون: بمعالي الأخلاق."},{"id":"wasitiyya:404","bookId":"wasitiyya","type":"section","seq":404,"chapter":"مقدمة المصنف","title":"312- وينهون عن","page":"ج1 ص130","text":"وينهون عن: سفسافها."},{"id":"wasitiyya:405","bookId":"wasitiyya","type":"section","seq":405,"chapter":"مقدمة المصنف","title":"313- وكل ما يقولونه أو يفعلونه من هذا أو غيره؛ فإنما هم فيه متبعون للكتاب والسنة","page":"ج1 ص130","text":"وكل ما يقولونه أو يفعلونه من هذا أو غيره؛ فإنما هم فيه متبعون للكتاب والسنة."},{"id":"wasitiyya:406","bookId":"wasitiyya","type":"section","seq":406,"chapter":"مقدمة المصنف","title":"314- وطريقتهم","page":"ج1 ص130","text":"وطريقتهم: هي دين الإسلام؛ الذي بعث الله به محمدا صلى الله عليه وسلم."},{"id":"wasitiyya:407","bookId":"wasitiyya","type":"section","seq":407,"chapter":"مقدمة المصنف","title":"من مزايا أهل السنة","page":"ج1 ص131","text":"] :"},{"id":"wasitiyya:408","bookId":"wasitiyya","type":"section","seq":408,"chapter":"مقدمة المصنف","title":"315- لكن لما أخبر صلى الله عليه وسلم","page":"ج1 ص131","text":"لكن لما أخبر صلى الله عليه وسلم: «أن أمته ستفترق على ثلاث وسبعين فرقة؛ كلها في النار إلا واحدة؛ وهي الجماعة» ."},{"id":"wasitiyya:409","bookId":"wasitiyya","type":"section","seq":409,"chapter":"مقدمة المصنف","title":"316- وفي حديث عنه أنه قال","page":"ج1 ص131","text":"وفي حديث عنه أنه قال: «هم من كان على مثل ما أنا عليه وأصحابي» ؛ صار المتمسكون بالإسلام المحض الخالص عن الشوب هم «أهل السنة والجماعة» ."},{"id":"wasitiyya:410","bookId":"wasitiyya","type":"section","seq":410,"chapter":"مقدمة المصنف","title":"317- وفيهم","page":"ج1 ص131","text":"وفيهم: الصديقون، والشهداء، والصالحون."},{"id":"wasitiyya:411","bookId":"wasitiyya","type":"section","seq":411,"chapter":"مقدمة المصنف","title":"318- ومنهم","page":"ج1 ص131","text":"ومنهم: أعلام الهدى، ومصابيح الدجى.\nأولوا المناقب المأثورة، والفضائل المذكورة."},{"id":"wasitiyya:412","bookId":"wasitiyya","type":"section","seq":412,"chapter":"مقدمة المصنف","title":"319- وفيهم","page":"ج1 ص131","text":"وفيهم: الأبدال."},{"id":"wasitiyya:413","bookId":"wasitiyya","type":"section","seq":413,"chapter":"مقدمة المصنف","title":"320- ومنهم","page":"ج1 ص131","text":"ومنهم: الأئمة؛ الذين أجمع المسلمون على\nهدايتهم ودرايتهم."},{"id":"wasitiyya:414","bookId":"wasitiyya","type":"section","seq":414,"chapter":"مقدمة المصنف","title":"321- وهم الطائفة المنصورة","page":"ج1 ص132","text":"وهم الطائفة المنصورة، الذين قال فيهم النبي صلى الله عليه وسلم: «لا تزال طائفة من أمتي على الحق ظاهرين؛ لا يضرهم من خالفهم ولا من خذلهم، حتى تقوم الساعة» .\n* * * *"},{"id":"wasitiyya:415","bookId":"wasitiyya","type":"section","seq":415,"chapter":"مقدمة المصنف","title":"خاتمة","page":"ج1 ص133","text":"فنسأل الله العظيم أن يجعلنا منهم.\nوأن لا يزيغ قلوبنا بعد إذ هدانا، ويهب لنا من لدنه رحمة؛ إنه هو الوهاب.\nوالحمد لله رب العالمين، وصلواته وسلامه على سيدنا محمد وآله وعلى سائر المرسلين والنبيين، وآل كل وسائر الصالحين.\n* * * *\nتمت، والحمد لله في عشي يوم الجمعة، في أوائل العشر الوسط لرمضان المعظم سنة ست وثلاثين وسبعمائة، بالمدرسة الظاهرية، داخل دمشق المحروسة على يدي معلقها محمد بن محمد بن محمد بن علي بن عبد الرحمن بن ... لطف الله به، وعفا عنه، وجعله من أهل السنة والجماعة - لا رب غيره ولا مولى سواه.\n* * * *"}]};